\begin{definition}[$k$-Tightest Neighbors Graph (TNG)] 
If the fully connected graph of the dataset $X$ is $G=$ $\{X,E\},E=(e_{ij})=\|x_i-x_j\|$ $\forall x_i,x_j\in X$, we define that the graph $TNG(k)$ is a subgraph of $G$ with 
\begin{equation}
TNG(k)=\{X,E_k\}
\end{equation}
\begin{equation}
E_k = (e_{ij}) = 
\begin{cases} 
\|x_i - x_j\| & \text{if } x_i \in TN(k, x_j), \\
0 & \text{otherwise}.
\end{cases}
\end{equation}
we say that $TNG(k)$ is the induced subgraph of $G$ by the $k$-tightest neighbors.
\end{definition}

\begin{theorem}
	$TNG(0) \subseteq TNG(1) \subseteq \cdots \subseteq TNG(k) \subseteq \cdots \subseteq TNG(m-1) = G$, as $k$ increases, the connectivity of $TNG(k)$ increases, and the number of branches in the graph decreases.
\end{theorem}

