\begin{theorem}
If a dataset \( X \) is ADD with a perfect partition \( X_1, X_2, \dots, X_K \), where \( |X_i|=m_i \) for \( i=1, 2, \dots, K \) and \( m_i \leq m_{i+1} \), then for all \( x_i \in X_i \) (\( i=1,2,\dots,K \)), the following holds:  
\begin{equation}
TN(m_i-1, x_i) = X_i.
\end{equation}
\end{theorem}


\begin{definition}[\textbf{Connectedly Dividable, CD}]
	A dataset $X$ is said as connectedly dividable (CD), that is, there exists a threshold $d$ and set 
	\begin{equation}
	E_d=(e_{ij})=\left\{
	\begin{aligned}
		||x_i-x_j|| , & \text{if}\ ||x_i-x_j||\leq d\\
		0 , & \text{otherwise}
	\end{aligned}
	\right.
	\end{equation}
	the adjacency matrix $E_d$ of $X$ is a symmetric reducible matrix and it holds
	\begin{equation}
		P_l^T\cdots P_1^TE_dP_1\cdots P_l=\begin{pmatrix}
			X_1 & & & & \\
			& \ddots & & & \\
			& & X_i & & \\
			& & & \ddots & \\
			& & & & X_K
		\end{pmatrix}
		\label{CD}
	\end{equation}
	where $K$ is the number of clusters and $X_i,i=1,\cdots,K$ are symmetric irreducible sub-matrices, $P_1,\cdots,P_l$ are permutation matrices. We also call that $X_i,i=1,\cdots,K$ is a perfect partition (clustering) of $X$ in the sense of CD.
\end{definition}

\begin{theorem}
If the dataset $X$ satisfies the condition of Connectedly Dividable (CD), and there exists an integer $k > 0$, then the subgraph induced by $k$-tightest neighbors, $TN(k)$, of $X$ satisfies
\begin{equation}
P_l^T\cdots P_1^TE_kP_1\cdots P_l=\begin{pmatrix}Y_1&&&&\\&\ddots&&&\\&&Y_i&&\\&&&\ddots&\\&&&&Y_K\end{pmatrix},
\end{equation}
where each $Y_i$ corresponds to a connected component of the cluster graph derived from $X$, and each $Y_i$ is a symmetric, irreducible submatrix that is the same size as $X_i$. This implies that the clusters obtained using $k$-tightest neighbors are exactly the perfect partitions of $X$.

\vspace{5pt}

\noindent \textbf{Proof:} Since the dataset $X$ is CD, there exists $d > 0$ such that the matrix $E_d = (e_{ij}) = 
\begin{cases}
\| x_i - x_j \|, & \text{when } \| x_i - x_j \| \leq d \\
0, & \text{otherwise}
\end{cases}
$ 
is a symmetric, irreducible matrix, and it holds that
\begin{equation}
P_l^T\cdots P_1^TE_dP_1\cdots P_l=\begin{pmatrix}X_1&&&&\\&\ddots&&&\\&&X_i&&\\&&&\ddots&\\&&&&X_K\end{pmatrix},
\end{equation}
On one hand, it is evident that the subgraph $\{X, TN(k)\}$ contains $X_i$ as connected components, because $T(X_i) \subseteq TN(k), \forall i \in \{1, \dots, K\}$. On the other hand, $X_i$ and $X_j$ are separated in the subgraph $\{X, TN(k)\}$, as $e_{ij} = \|x_i - x_j \| = 0, \forall x_i \in X_i, x_j \in X_j$. Thus, $TN(k)$ and $E_d$ can be partitioned in the same manner, both exhibiting the same block diagonal structure.\qed
\end{theorem}


