    \centering
    \includegraphics[width=\linewidth]{tz_figures/tn_7.pdf}
    \caption{The $TNOF$ values distribution of noise datasets.}
    \label{fig:tnof1}
\end{figure}


\begin{definition}[Outlier]
A point \( x_i \) is considered an outlier if its \( TNOF \) satisfies the following condition:

\begin{equation} \label{eq:outlier}
\text{Outlier} = \{x_i \mid \forall x_i \in X, \text{TNOF}(x_i) > \theta \},
\end{equation}

where \( \theta \) is the threshold used to classify outliers, and it is defined as:\[\theta = \text{mean}(TNOF) + \alpha \times \text{std}(TNOF),\]

where \( \text{mean}(TNOF) \) is the mean of the \( TNOF \) values of all data points, \( \text{std}(TNOF) \) is the standard deviation of the \( TNOF \) values, and \( \alpha \) is an adjustment factor. Based on extensive experimentation, \( \alpha = 1 \) is found to be the ideal value for detecting outliers in most datasets.
\label{def:Outlier}
\end{definition}

Based on the above analysis, we propose an outlier detection algorithm based on local density and tightest neighbors, which is shown in Algorithm \ref{alg:tnof11}:

\begin{algorithm}[h]
\caption{Outlier Detection Algorithm based on Tightest Neighbors (TNOF)} \label{alg:tnof11}
\begin{algorithmic}[1]
    \State \textbf{Input:} Dataset $X$, number of tightest neighbors $k$
    \State \textbf{Output:} Outliers
    \State Initialize: $TN$, Outliers;
    \State Search for tightest neighbors: $TN = \text{SearchTN}(X, k)$;
    \State Calculate $TNOF$ of all points according to Equation~\ref{equ:tnof};
    \State Separate Outliers according to Equation~\ref{eq:outlier};
    \State \textbf{Return:} Outliers.
\end{algorithmic}
\end{algorithm}
