\begin{algorithm}[h]
\caption{AddtoMC} \label{alg:6}
\begin{algorithmic}[1] 
\State \textbf{Input:} Dataset
\State \textbf{Output:} MCs
\State $X \gets Dataset[MC == 0]$
\For{each $X_i \in X$}
    \For{each $MC_j \in MCs$}
        \State $d \gets \text{dist}(X_i, MC_j)$
        \If{$d \leq r_{MC_j}$}
            \State $X_i \gets [MC]$
