\begin{algorithm}[h]
\caption{DefineMacroC} \label{alg:7}
\begin{algorithmic}[1]
\State \textbf{Input:} MCs; $n_{\text{micro}}$; $k$
\State \textbf{Output:} Clusters
\For{each $MC_i \in MCs$}
