\begin{algorithm}[h]
\caption{AddMCtoMacroC} \label{alg:8}
\begin{algorithmic}[1]
\State \textbf{Input:} MCs; radius $r$
\State \textbf{Output:} MCs
\State $MC \gets MCs[\text{MacroC} == 0]$
\For{each $MC_i \in MC$}
    \For{each $MC_j \in MCs$}
        \State $d \gets \text{dist}(MC_i, MC_j)$
