\begin{algorithm}[h]
\caption{UpdateMC} \label{alg:9}
\begin{algorithmic}[1]
\State \textbf{Input:} Dataset; MCs
\State \textbf{Output:} MCs
\For{each $MC_i \in MCs$}
    \State $num[MC_i] \gets \text{count}(Dataset[MC_i])$
    \For{each dimension $d_j \in d$}
        \State $MC_i[\text{centerCoordinate}^j] \gets \text{mean}(Dataset^j)$
