\begin{algorithm}[h]
\caption{KillMCs} \label{alg:11}
\begin{algorithmic}[1]
\State \textbf{Input:} Dataset; MCs; $N$
\State \textbf{Output:} MCs
\For{each $MC_i \in MCs$}
    \If{$\text{len}(Dataset[MCs == i]) < N$}
        \State delete $MC_i$
        \State $Dataset[MCs == i] \gets 0$
    \EndIf
