% \begin{equation}
%     {{\ddot y}_{com,t}} = \dot J({q_{2,t}}){{\dot q}_{2,t}} + J({q_{2,t}}){{\ddot q}_{2,t}}
% \end{equation}

% The robot's jump height is determined by the combined kinetic and potential energy at takeoff, expressed as:

% \begin{equation}
%     W_{\text{takeoff}} = \frac{1}{2} m_{\text{total}} \dot{y}_{\text{com,takeoff}}^2 + mg y_{\text{com,takeoff}}
% \end{equation}

% The optimization objective is to maximize the total mechanical energy at the moment of lift-off, expressed as:
% \begin{equation}
% \mathop {\min }\limits_{r,{S_0},\Delta \theta } f(a,{S_0},\Delta \theta ) = - {W_{\text{takeoff}}}
% \end{equation}

The design parameters are subject to the following structural constraints:
\begin{equation}
    s.t. \left\{ \begin{array}{l}
        {r_{\min }} \leq r \leq {r_{\max }}\\
        {S_{0,\min }} \leq {S_0} \leq {S_{0,\max }}\\
        \Delta {\theta _{\min }} \leq \Delta \theta  \leq \Delta {\theta _{\max }}
        \end{array} \right.   
\end{equation}

% \begin{equation}
%     h = \frac{W_{takeoff}}{{{m_{total}}g}} - {h_{end}}
% \end{equation}

\begin{algorithm}
    \caption{Optimal Knee Joint Design Parameter Selection via High-Explosive Jump Control}
    \begin{algorithmic}[1]
        \Require A set of knee design parameters $\{P_1, P_2, \dots, P_n\}$
        \Ensure Maximum take-off energy and the corresponding structure parameter

        \State $max\_energy \gets -\infty$
        \State $optimal\_param \gets$ None

        \For{$i \gets 1$ to $n$}
            \State $energy \gets \text{simulateJump}(P_i)$ \Comment{Simulate high burst jump for structure parameter $P_i$ and record take-off energy}
            \If{$energy > max\_energy$}
                \State $max\_energy \gets energy$
                \State $optimal\_param \gets P_i$
            \EndIf
        \EndFor

        \State \Return $max\_energy, optimal\_param$
        \end{algorithmic}
\end{algorithm}

