    \includegraphics[width=0.7\linewidth]{data/time_comparison_matlab_vs_motives.png}
    \caption{Time comparison between algorithm \cite{Alf22} and \code{motives} package for the computational verification of Mozgovoy's conjectural formula. \cite{Alf22} data is limited to $g\le 11$ because the program reached the memory limit for the machine for that $g$.}
