\section{Proofs omitted from the main body}

\begin{proof}[Proof of \cref{thm:existence_of_dist}]
	Consider the following LP
	\begin{alignat*}{2}
	  \text{maximize} & \quad & t \qquad \qquad & \tag{P'} \label{primal} \\
          \text{subject to} && \sum_{d \in K} \frac{v(\{e \in U:c_e\le d_e\} )}{v(U)}\cdot
          x_d & \ge t \qquad \forall c \in K \\
	  && \sum_{d \in K}x_d & = 1 \\
	  && x & \ge 0.
        \end{alignat*}
	Let $M \in \mathbb{R}^{K\times K}$ be a matrix with rows and columns indexed by
        elements in $K$ defined as $M_{c,d} = \frac{v(\{e \in U:c_e\le d_e\} )}{v(U)}$ for
        every $c,d \in K$. 
	Let $\vec{1}$ be the all-ones vector and let $J$ be the all-ones matrix of
        dimension $|K| \times |K|$. 
	Then \eqref{primal} can be written succinctly as
        \begin{equation*}
	  \text{maximize} \quad t \qquad \text{subject to} \qquad  Mx \ge  t\vec{1}, \quad
	  \vec{1}^\intercal x = 1, \quad x \ge 0.
	\end{equation*}	
        The dual LP is
        \begin{equation}
	  \text{minimize} \quad \rho \qquad \text{subject to} \qquad  M^\intercal y \le  \rho\vec{1}, \quad
	  \vec{1}^\intercal y = 1, \quad y \ge 0. \tag{D'} \label{dual}
	\end{equation}	
	Let $(y,\rho )$ be a feasible solution to \eqref{dual}. 
	By subadditivity of $v$, for every $c,d \in K$, we have that 
        $v(\{e \in U:c_e\le d_e\} )+v(\{e \in U:d_e\le c_e\} ) \ge v(U)$. 
	Hence, we get that 
        $M_{c,d}+M_{d,c} = \frac{v(\{e \in U:c_e\le d_e\} )+v(\{e \in U:d_e\le c_e\} )}{v(U)} \ge 1$ for every $c,d \in K$. 
	In other words, $M+M^\intercal \ge J$, that is, every entry of $M+M^\intercal $ is
        at least the corresponding entry of $J$. 
	Now, 
	\begin{align*}
		\rho = \rho (y^\intercal \vec{1}) = y^\intercal (\rho \vec{1}) \ge y^\intercal My = \frac{1}{2}y^\intercal (M+M)y = \frac{1}{2}y^\intercal (M+M^\intercal )y \ge \frac{1}{2}y^\intercal J y = \frac{1}{2},
	\end{align*}
	where we used the fact that $\vec{1}^\intercal y=1$ and the fact that $y^\intercal My = y^\intercal M^\intercal y$.
	Hence we conclude that $\rho \ge \frac{1}{2}$ for every feasible solution of \eqref{dual}.
	In particular, this implies that the optimal value of \eqref{dual}, and hence
        \eqref{primal}, is at least $\frac{1}{2}$. 

	Now let $(x,t)$ be an optimal solution for \eqref{primal}.
	Consider the distribution $\mathcal{D}^*$ over vectors in $K$, where the
        probability of sampling a vector $d \in K$ is $x_d$. 
	Then, for all $c \in K$, we have $\Ex_{d\sim \mathcal{D}^*}[v(\{e \in U:c_e\le
          d_e\} )] = \sum_{d \in K} v(\{e \in U:c_e\le d_e\} ) x_d \ge t\cdot v(U) \ge \frac{1}{2}v(U)$.
	This proves the lemma.
\end{proof}

\begin{lemma}\label{lem:no_pure_strategy}
	For every $d \in \mathbb{R}^U_+$ with $d(U)\le B$, there exists $c \in \mathbb{R}^U_+$ with $c(U)\le B$ such that $v(\{e \in U:c_e\le d_e\} ) \le v(e^*)$.
\end{lemma}
\begin{proof}
	Let $Q = \{e \in U:d_e>0\}$. 
	Let $e'$ be an arbitrary element in $Q$.
	Let $\epsilon = \frac{1}{n}\min_{e \in Q}\{d_e\} > 0$.
	Construct the vector $c$ by setting $c_e = d_e+\epsilon $ for all $e \in U-e'$, and set $c_{e'} = d_{e'} - (n-1) \epsilon $.
	Then note that $c(U)=d(U)\le B$. Moreover, $c_e \ge 0$ for all $e \in U$ by our choice of $\epsilon $.
	Now, $v(\{e \in U:c_e\le d_e\} ) = v(e') \le  \max_{e \in U}\{v(e)\} = v(e^*)$.
\end{proof}

