\mathbf{i}(t) 
\end{pmatrix} + \mathbf{Du}(t)
\end{aligned}
\end{equation}
where $\mathbf{G}_{11} \in \R^{n_1\times n_1}$, $\mathbf{G}_{12} \in \R^{n_1\times n_2}$, $\mathbf{G}_{22} \in \R^{n_2\times n_2}$, $\mathbf{W}_{1} \in \R^{n_1\times m}$, $\mathbf{W}_{2} \in \R^{n_2\times m}$, $\mathbf{C}_{1} \in \R^{n_1\times n_1}$, $\mathbf{v}_{1} \in \R^{n_1}$, $\mathbf{v}_{2} \in \R^{n_1}$, $\mathbf{B}_{1} \in \R^{n_1 \times p}$, $\mathbf{B}_{2} \in \R^{n_2 \times p}$, $\mathbf{L}_{1} \in \R^{q \times n_1}$, and $\mathbf{L}_{2} \in \R^{q\times n_2}$.\\
Assuming now that the submatrix $\mathbf{G}_{22}$ is nonsingular 
