%%\mathbf{G}_{11}\mathbf{v}_1 - \mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{G}_{21}\mathbf{v}_1 - \mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{A}_{2}\mathbf{i} - \mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{B}_2\mathbf{u}+\mathbf{A}_{1}\mathbf{i} +\mathbf{C}_{11}\dot{\mathbf{v}}_1 =\mathbf{B}_1\mathbf{u} \\
%\end{aligned}
