\begin{equation*}
\begin{aligned}
(\mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{G}_{12}^T -\mathbf{W}_{1}^T)\mathbf{v}_1(t)+ \mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{W}_{2}\mathbf{i}(t)+\mathbf{M}\dot{\mathbf{i}}(t)\\= \mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{B}_{2}\mathbf{u}(t)
\end{aligned}
\end{equation*}
\begin{equation*}
\begin{aligned}
\mathbf{y}(t) = (\mathbf{L}_{1}- \mathbf{L}_{2}\mathbf{G}_{22}^{-1}\mathbf{G}_{12}^T)\mathbf{v}_{1}(t) - \mathbf{L}_{2}\mathbf{G}_{22}^{-1}\mathbf{W}_{2}\mathbf{i}(t)\\ + (\mathbf{L}_{2}\mathbf{G}_{22}^{-1}\mathbf{B}_{2}+\mathbf{D})\mathbf{u}(t)
\end{aligned}
\end{equation*} 
This can be put together in the following descriptor form:
\begin{equation} \label{111}
\begin{aligned}
\begin{pmatrix}
\mathbf{C}_{1} & \mathbf{0} \\
\mathbf{0} & \mathbf{M} 
\end{pmatrix}\begin{pmatrix}
\dot{\mathbf{v}}_1(t) \\
\dot{\mathbf{i}}(t) 
\end{pmatrix} = \\-\begin{pmatrix}
\mathbf{G}_{11} - \mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{G}_{12}^T & \mathbf{W}_1- \mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{W}_{2} \\
\mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{G}_{12}^T -\mathbf{W}_{1}^T & \mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{W}_{2}
\end{pmatrix}\begin{pmatrix}
\mathbf{v}_1(t) \\
\mathbf{i}(t) 
\end{pmatrix} \\+ \begin{pmatrix}
\mathbf{\mathbf{B}_1-\mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{B}_2} \\
\mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{B}_{2} 
\end{pmatrix}\mathbf{u}(t)\\
\mathbf{y}(t)= \begin{pmatrix}
\mathbf{L}_{1}- \mathbf{L}_{2}\mathbf{G}_{22}^{-1}\mathbf{G}_{12}^T \quad
\mathbf{L}_{2}\mathbf{G}_{22}^{-1}\mathbf{W}_{2} 
\end{pmatrix}\begin{pmatrix}
{\mathbf{v}_1}(t) \\
{\mathbf{i}}(t) 
\end{pmatrix}\\ + (\mathbf{L}_{2}\mathbf{G}_{22}^{-1}\mathbf{B}_{2}+\mathbf{D})\mathbf{u}(t)
\end{aligned}
\end{equation}
The above is a nonsingular (i.e., regular) state-space model which can be reduced normally by the EKS and AEKS procedures of Algorithms \ref{eksm_alg} and \ref{ueks_alg}.

