\subsection{Sparse Implementation of EKS and AEKS} \label{5.3}
% \dimitris{Maybe change order in this sentence-> Algorithm 1 is inefficent for...since..}
The Algorithms \ref{eksm_alg} and \ref{ueks_alg} are now applicable to the nonsingular descriptor model (\ref{111}), but their execution is computationally inefficient because the inversion of $\mathbf{G}_{22}$ renders the matrices dense and hinders the solution procedure. In this subsection, we present efficient ways to implement Algorithm \ref{eksm_alg} (and likewise Algorithm \ref{ueks_alg}) by preserving the original sparse form of the system matrices.
\subsubsection{\textbf{Construction of RHS}} The input-to-state and state-to-output connectivity matrices
\begin{equation} \label{421}
\mathbf{B} \equiv \begin{pmatrix}
\mathbf{B}_1-\mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{B}_2 \\
\mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{B}_{2} 
\end{pmatrix} , \quad \mathbf{L}^T \equiv \begin{pmatrix}
\mathbf{L}_{1}^T- \mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{L}_{2}^T \\
\mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{L}_{2}^T 
\end{pmatrix} 
\end{equation} 
are explicitly constructed to compute the input matrix $\mathbf{B}_E$ of Algorithm \ref{eksm_alg} and to obtain the reduced-order model through (\ref{20}). The products $\mathbf{G}_{22}^{-1}\mathbf{B}_2$ and $\mathbf{G}_{22}^{-1}\mathbf{L}_{2}^T$ are computed by $p$ and $q$ sparse linear solves, respectively.
\subsubsection{\textbf{Sparse linear system solutions}} The system matrix
\begin{equation}\label{422}
\mathbf{A} \equiv - \begin{pmatrix}
\mathbf{G}_{11} - \mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{G}_{12}^T & \mathbf{W}_1- \mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{W}_{2} \\
\mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{G}_{12}^T -\mathbf{W}_{1}^T & \mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{W}_{2}
\end{pmatrix}
\end{equation}
of the model given in (\ref{111}) is rendered dense due to the inversion of $\mathbf{G}_{22}$. The linear system solutions with $\mathbf{A}$ in steps 3, 7 of Algorithm \ref{eksm_alg} can be handled by partitioning the right-hand-side of these systems conformally to $\mathbf{A}$, i.e., $\mathbf{R} =  \begin{pmatrix}
\mathbf{R}_1 \\
\mathbf{R}_2 \\
\end{pmatrix}$
with $\mathbf{R}_1 \in \R^{n_1\times p}$, $\mathbf{R}_2\in \R^{m \times p}$, 
%is dense but is only used in linear system solutions with  $\mathbf{A}$ in steps 2 and 7 of Algorithm \ref{eksm_alg}., then their solution can be implemented efficiently by keeping the sub-blocks in their original sparse form as:
and implementing their solution efficiently by keeping all the sub-blocks in their original sparse form as follows: 
\begin{equation} \label{122}
\begin{aligned}
\begin{pmatrix}
-\mathbf{G}_{11} &-\mathbf{W}_{1} & -\mathbf{G}_{12} \\
\mathbf{W}_1^T &\mathbf{0} & \mathbf{W}_2^T \\
-\mathbf{G}_{12}^T & -\mathbf{W}_2&-\mathbf{G}_{22} 
\end{pmatrix}\begin{pmatrix}
\mathbf{V}_1 \\
\mathbf{V}_2 \\
\mathbf{T}
\end{pmatrix} = \begin{pmatrix}
\mathbf{R}_1 \\
\mathbf{R}_2 \\
\mathbf{0}
\end{pmatrix}
\end{aligned}
\end{equation}
where $\mathbf{T} \in \R^{n_2 \times p}$ is a temporary sub-matrix.
% A comparable approach for the reduction of power systems via the low-rank ADI method was presented in \cite{freitas}, but is more complicated computationally and is applicable to RC-only circuits. \\
\subsubsection{\textbf{Sparse matrix-vector products}} The matrix-vector products with $\mathbf{V}^{(j)}$ in step 7 of Algorithm \ref{eksm_alg} can be implemented efficiently by observing that:
%Firstly, as described previously the matrix logarithm requires the operation $\mathbf{Y}\mathbf{K}^{(j)}\mathbf{r}= (\mathbf{A}+i\omega_2\mathbf{E})(\mathbf{A}+i\omega_1\mathbf{E})^{-1} \mathbf{K}^{(j)}\mathbf{r}$. To preserve the sparse linear solve and the sparse matrix-vector product we treat the system as follows.
\begin{equation}\label{424}
\begin{aligned}
\mathbf{A} =\begin{pmatrix}
-\mathbf{G}_{11}  & -\mathbf{W}_{1}\\
\mathbf{W}_1^T &\mathbf{0}
\end{pmatrix}+ \begin{pmatrix}
\mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{G}_{12}^T & \mathbf{G}_{12}\mathbf{G}_{22}^{-1}\mathbf{W}_{2}\\
-\mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{G}_{12}^T&-\mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}\mathbf{W}_{2}\end{pmatrix} \\=
\begin{pmatrix}
-\mathbf{G}_{11}  & -\mathbf{W}_{1}\\
\mathbf{W}_1^T &\mathbf{0}
\end{pmatrix} + \begin{pmatrix}
-\mathbf{G}_{12} \\
\mathbf{W}_{2}^T
\end{pmatrix}\mathbf{G}_{22}^{-1}\begin{pmatrix}
-\mathbf{G}_{12}^T &
-\mathbf{W}_{2}
\end{pmatrix}
\end{aligned}
\end{equation}
Therefore, the product $\mathbf{A} \mathbf{V}^{(j)}$ with  $p$ vectors $\mathbf{V}^{(j)}$ can be carried out by a sparse solve $\mathbf{G}_{22}\mathbf{V} = \begin{pmatrix}
-\mathbf{G}_{12}^T &
-\mathbf{W}_{2}
\end{pmatrix}\mathbf{K}^{(j)}
$, followed by a sum of products $\begin{pmatrix}
-\mathbf{G}_{11}  & -\mathbf{W}_{1}\\
\mathbf{W}_1^T &\mathbf{0}
\end{pmatrix}\mathbf{K}^{(j)} + \begin{pmatrix}
-\mathbf{G}_{12} \\
\mathbf{W}_{2}^T
\end{pmatrix}\mathbf{V}$.
\vspace{1.1mm}
\subsubsection{\textbf{Construction of system matrix}} In order to construct and then reduce the dense system matrix of (\ref{422}), we need to employ sparse solves with the submatrix $\mathbf{G}_{22}$. Since usually $n_2 << n_1$, it is better to first compute the left-solves $\mathbf{G}_{12}\mathbf{G}_{22}^{-1}$ and $\mathbf{W}_{2}^T\mathbf{G}_{22}^{-1}$, followed by products with $\mathbf{G}_{12}^T$ and $\mathbf{W}_{2}$. The left-solves can be performed as $\mathbf{G}_{22}\mathbf{V} =\mathbf{G}_{12}$ and $\mathbf{G}_{22}\mathbf{V} =\mathbf{W}_{2}^T$, where $\mathbf{V}$ contains the \textit{rows} of each left-solve.  

\section{Efficient Computation of the Reduced-Order Response and Transfer Function} \label{PAR}
%\red{[At least any references to the following should be removed: 1) superposition, 2) parallel computation of ROM, 3) passivity.]. Also, a lot of notation changes are needed.}
%While in the previous subsections we emphasized on the efficient execution of the proposed methodology, it still can not handle many-terminal models. To this end, we consider the superposition principal of Linear Time invariant (LTI) models.
%Using the superposition property, 
To efficiently compute the transfer function and the output response of a multi-input multi-output (MIMO) descriptor model like (\ref{state}), we can consider the following single-input multi-output (SIMO) subsystems:
\begin{equation}
\begin{aligned} \label{super_state}
\mathbf{E}\frac{d \mathbf{x}(t)}{d t} = \mathbf{A x}(t) + \mathbf{b}_i u_i(t), \\
\mathbf{y}_i(t) = \mathbf{L x}(t) + \mathbf{d}_i u_i(t)
\end{aligned}
\end{equation}
where $\mathbf{b}_i$ and $\mathbf{d}_i$ are the $i$-th columns of matrices $\mathbf{B}$ and $\mathbf{D}$, respectively, and $u_i(t)$ is the $i$-th input ($i=1,\dots,p$). From these SIMO subsystems, the output of the MIMO descriptor system is $\mathbf{y}(s)= \sum_{n=1}^{p}\mathbf{y}_i(s) = \sum_{n=1}^{p}\mathbf{h}_i(s) u_i(s)$, where

\begin{equation*}
\mathbf{h}_i(s) = \mathbf{ L}(s\mathbf{ E} - \mathbf{ A})^{-1} \mathbf{ b}_i + \mathbf{ d}_i   
\end{equation*}

\noindent
This effectively represents the superposition property of linear and time-invariant (LTI) systems.

The above decomposition can be employed for the parallel computation of the reduced-order MIMO transfer function. In particular, for each SIMO subsystem of (\ref{super_state}), a projection matrix $\mathbf{V}_i \in \R^{N \times r}$ can be computed, whose columns span the $r$-dimensional EKS (or AEKS):
\begin{equation*}
\label{Eq:eksm_sup}
\mathcal{K}_r^E(\mathbf{A}_{E},\mathbf{b}_{i}^{E}) = \mathcal{K}_{r/2}(\mathbf{A}_{E},\mathbf{b}_{i}^{E}) + \mathcal{K}_{r/2}(\mathbf{A}_{E}^{-1},\mathbf{b}_{i}^{E}) =
\end{equation*}
\begin{equation*}
span \{\mathbf{b}_{i}^{E},  \mathbf{A}_{E}^{-1}\mathbf{b}_{i}^{E}, \mathbf{A}_{E}\mathbf{b}_{i}^{E},\mathbf{A}_{E}^{-2}\mathbf{b}_{i}^{E},\mathbf{A}_{E}^{2}\mathbf{b}_{i}^{E},\mathbf{A}_{E}^{-3}\mathbf{b}_{i}^{E},\dots,  
\end{equation*}
\begin{equation}\label{195}
\mathbf{A}_{E}^{(r/2)-1}\mathbf{b}_{i}^{E}, \mathbf{A}_{E}^{-r/2}\mathbf{b}_{i}^{E}\}
\end{equation} 
where $\mathbf{b}_{i}^{E} \equiv \mathbf{A}^{-1}\mathbf{b}_i $. The computation of the projection matrices (by Algorithm \ref{eksm_alg} or \ref{ueks_alg}) is independent from one another and can be performed in parallel. The reduced-order SISO subsystems can then be computed in parallel as:
\begin{equation} \label{tran_super}
\mathbf{\tilde E}_i = \mathbf{V}_i^T\mathbf{ E}\mathbf{V}_i, \quad \mathbf{\tilde A}_i = \mathbf{V}_i^T\mathbf{ A}\mathbf{V}_i, \quad \mathbf{\tilde b}_i = \mathbf{V}_i^T\mathbf{ b}_i, \quad \mathbf{\tilde L}_i = \mathbf{ L}\mathbf{V}_i
\end{equation}
The $i$-th column of the MIMO reduced-order transfer function would then be:
\begin{equation} \label{h(s)_super}
\mathbf{\tilde h}_i(s)= \mathbf{\tilde L}_i(s\mathbf{\tilde E}_i - \mathbf{\tilde A}_i)^{-1} \mathbf{\tilde b}_i + \mathbf{d}_i
\end{equation}
and the whole MIMO reduced-order transfer function can be derived as the concatenation:
\begin{equation}\label{H_i}
\mathbf{\tilde H}(s) =   [\mathbf{\tilde h}_1(s);\mathbf{\tilde h}_2(s);\dots;\mathbf{\tilde h}_p(s)]  
\end{equation}

It must be noted that this decomposition it is better combined with direct solvers, since the computation of the Krylov subspace requires sparse solves with $\mathbf{A}$ and $\mathbf{E}$ as we mentioned previously. Using direct solvers, one  can pre-compute the proper decomposition of the above matrices and then re-use them in each parallel computation. 

%It must be noted that there is no guarantee that the passivity of the reduced-order models obtained using the superposition property is preserved. In recent years, however, the focus of MOR has been shifted from provably passive models to passivity enforcement \textit{after} efficient reduction. A wealth of passivity enforcement techniques, such as \cite{pass}, have been developed to assure passivity of the reduced-order models obtained using the superposition property.      


