\subsection{Proof of Proposition \ref{prop2}}

\noindent \textbf{Proof:} Consider $\max_{\mathbb{P}\in \mathcal{P}(\mathcal{S}, \kappa)}\mathbb{E}_{\mathbb{P}}[V(\xeg,\boldsymbol{\omega}_s)]$ term under the ambiguity set \eqref{ambguity_set} with dual variables indicated within brackets:


\begin{align} \label{model:inner_max_expect}
\max_{p} \ &\sum_{s\in S}p_s V(\xeg,\boldsymbol{\omega}_s)\\
\text{s.t.} \ & \sum_{s\in \mathcal{S}}p_s d^{\text{e}}_{sit} \leq \mu^{\text{e}}_{it}+\bar{\Delta}^e_{i}&  i \in \Ne, t\in \Te, \quad [\beta^1_{it}] \notag\\
& -\sum_{s\in \mathcal{S}}p_s d^{\text{e}}_{sit} \leq  -\mu^{\text{e}}_{it}-\underline{\Delta}^e_{i} &  i \in \Ne, t\in \Te, \quad [\beta^2_{it}]\notag\\
&\sum_{s\in \mathcal{S}}p_s d^v_{sit} \leq \mu^{v}_{it}+\bar{\Delta}^v_{i} & v\in \mathcal{V},  i \in \Ne, t\in \Te, \quad [\gamma^1_{vit}]\notag\\
&-\sum_{s\in \mathcal{S}}p_s d^v_{sit} \leq  -\mu^{v}_{it}-\barbelow{\Delta}^v_{i} & v\in \mathcal{V},  i \in \Ne, t\in \Te, \quad [\gamma^2_{vit}]\notag\\
&\sum_{s\in \mathcal{S}}p_s \dg_{sk\tau}\leq \mu^{\text{g}}_{k\tau}+\bar{\Delta}^g_{k} & k \in \Ng, \tau \in \Tg, \quad [\pi^1_{k\tau}]\notag\\
& -\sum_{s\in \mathcal{S}}p_s \dg_{s k\tau} \leq -\mu^{\text{g}}_{k\tau}-\barbelow{\Delta}^g_{k} & k \in \Ng, \tau \in \Tg, \quad [\pi^2_{k\tau}]\notag\\
& \sum_{s\in S} p_s =1 & i\in \mathcal{N}, \quad  [\xi]\notag\\
&p_s\in \mathbb{R}^{|S|} & s\in \mathcal{S}, i\in \notag \mathcal{N}
\end{align}

We write the dual of \eqref{model:inner_max_expect} as the following minimization problem:
\begin{subequations}\label{model:inner_prob_companct}
    \begin{align}
\min \quad &\Psi^{\text{obj}}  + \xi\\
\text{s.t. }\ & \xi \geq V(\xeg,\boldsymbol{\omega}_s)-\Psi^{\text{cntr}}_{s}, \qquad s\in \mathcal{S}\label{c1:inner_prob_compact}
\end{align}
\end{subequations}


where $\Psi^{\text{cntr}}_{s}$ and $\Psi^{\text{obj}}$ are defined as
\begin{align*}
\Psi^{\text{cntr}}_{s} =&  \sum_{i\in \mathcal{N}^{\text{e}}}\sum_{ t \in \mathcal{T}^{\text{e}}} \left [\beta^1_{it}d^{\text{e}}_{sit} -\beta^2_{it}d^{\text{e}}_{sit} \right] +\sum_{i\in \mathcal{N}^{\text{e}}}\sum_{ t \in \mathcal{T}^{\text{e}}}\sum_{v\in \mathcal{V}} \left [\gamma^1_{vit}d^{\text{v}}_{sit} -\gamma^2_{vit}d^{\text{v}}_{sit} \right] + \sum_{k\in \mathcal{N}^{\text{g}}} \sum_{ \tau \in \mathcal{T}^{\text{g}}} \left [\pi^1_{k\tau} d^{\text{g}}_{sk\tau} -\pi^2_{vk\tau} d^{\text{g}}_{sk\tau} \right], s\in S \notag \\
\Psi^{\text{obj}}= & \sum_{i\in \mathcal{N}^{\text{e}}, t \in \mathcal{T}^{\text{e}}}\left[ (\mu^{\text{e}}_{it}+\bar{\Delta}^e_i)\beta^1_{it}-(\mu^{\text{e}}_{it}+\barbelow{\Delta}^e_i)\beta^2_{it} 
+\sum_{v\in \mathcal{V}}( (\mu^{v}_{it}+\bar{\Delta}^v_i)\gamma^1_{vit}-(\mu^{v}_{it}+\barbelow{\Delta}^v_i)\gamma^2_{vit}) \right] \\
&+\sum_{k\in \mathcal{N}^{\text{g}}, \tau \in \mathcal{T}^{\text{g}}}\left[ (\mu^{\text{g}}_{k\tau}+\bar{\Delta}^{\text{g}}_{k})\pi^1_{k\tau}-(\mu^{\text{g}}_{k\tau}+\barbelow{\Delta}^{\text{g}}_{k})\pi^2_{k\tau} \right]
\end{align*}

The constrain of \eqref{c1:inner_prob_compact} has to be satisfied for all, including the largest scenarios (i.e., maximum). Therefore, problem~\eqref{model:inner_prob_companct} is equivalent to:
\begin{align}\label{model:expet_DRO}
\min \ & \Psi^{\text{obj}}+\max_{s\in \mathcal{S}} \{V(\xeg,\boldsymbol{\omega}_s)-\Psi^{\text{cntr}}_s\}
\end{align}

Now consider the second inner maximization term with \cvar{} measure:

\begin{align*}
\max_{\mathbb{P}\in \mathcal{P}(\mathcal{S}, \kappa)}\ \cvar^\alpha_{\mathbb{P}}(V(\xeg,\boldsymbol{\omega}_s))=\max_{\mathbb{P}\in \mathcal{P}(\mathcal{S}, \kappa)}\ \min_{\eta\in \mathbb{R}} \{\eta +\frac{1}{1-\alpha}\mathbb{E}_{\mathbb{P}}[\max(V(\xeg,\boldsymbol{\omega}_s)-\eta,0)] \} 
\end{align*}
Note that the term inside the minimization expression is convex on $\eta$ \citep{SarykalinEtal2008_CVaR_VaR}, and the  \cvar{} is concave on $\mathbb{P}$ \citep{RahimianMehrotra2019_DRO_review}. Therefore, the order of maximum and minimum operators can exchange \citep{Sion1958_MinMax} to yield:


\begin{align}\label{model:cvar_DRO}
\max_{\mathbb{P}\in \mathcal{P}(\mathcal{S}, \kappa)}\ \cvar^\alpha_{\mathbb{P}}(V(\xeg,\boldsymbol{\omega}_s))=\min_{\eta\in \mathbb{R}} \{\eta +\frac{1}{1-\alpha}\max_{\mathbb{P}\in \mathcal{P}(\mathcal{S}, \kappa)} \mathbb{E}_{\mathbb{P}}[\max(V(\xeg,\boldsymbol{\omega}_s)-\eta,0)] \} 
\end{align}
Following a similar approach for first maximization term, we can write \eqref{model:cvar_DRO} as:

\begin{subequations}
\begin{align*}
\min \quad & \eta +\frac{1}{1-\alpha}(\Psi^{\text{obj}}+\xi)\\
\text{s.t. }\ & \Psi^{\text{cntr}}_s+\xi \geq V(\xeg,\boldsymbol{\omega}_s)-\eta, \qquad  s\in S\\
& \Psi^{\text{cntr}}_s+\xi \geq 0, s\in S
\end{align*}
\end{subequations}
Since the first set of constraints has to be satisfied for every $s \in \mathcal{S}$, we equivalently have:
\begin{subequations}
\begin{align*}
\min \quad & \eta +\frac{1}{1-\alpha}(\Psi^{\text{obj}}+\xi)\\
\text{s.t. }\ & \eta \geq \max_{s\in S} \{V(\xeg,\boldsymbol{\omega}_s)- \Psi^{\text{cntr}}_s-\xi\}\\
& \Psi^{\text{cntr}}_s+\xi \geq 0, s\in S
\end{align*}
\end{subequations}

Minimizing the right-hand-side of the first constraints is equivalent to minimizing $\eta$, therefore:

\begin{align*}
\min \quad & \max_{s\in S} \{V(\xeg,\boldsymbol{\omega}_s)- \Psi^{\text{cntr}}_s\} + \frac{\alpha \xi}{1-\alpha} +\frac{\Psi^{\text{obj}}}{1-\alpha}\\
\text{s.t. }\ &\Psi^{\text{cntr}}_s+\xi \geq 0, s\in S
\end{align*}

Then, the model \eqref{model:dro_orig} becomes:

\begin{align*} 
\min_{x\in \mathcal{X}} \ & \CeO \xe + \CgO \xg \\
& + \lambda \left[\Psi^{\text{obj}} +\max_{s\in S} \{V(\xeg,\boldsymbol{\omega}_s)- \Psi^{\text{cntr}}_s\}\right] \\
& + (1-\lambda)\left[(\max_{s\in S} \{V(\xeg,\boldsymbol{\omega}_s)- \Psi^{\text{cntr}}_s\}+\frac{\alpha \xi}{1-\alpha}+\frac{\Psi^{\text{obj}}}{1-\alpha}\right]\\
\text{s.t. }\ &\Psi^{\text{cntr}}_s+\xi \geq 0& s\in S
\end{align*}
\noindent which is equivalent to the following MILP:
  \begin{subequations}\label{model:DRO-EF2}
\begin{align}
\min \ & \CeO \xe + \CgO \xg + \lambda \Psi^{\text{obj}} +\delta  + (1-\lambda)\left[\frac{\alpha \xi}{1-\alpha}+\frac{\Psi^{\text{obj}}}{1-\alpha}\right]\\
\text{s.t. }\ &\Psi^{\text{cntr}}_s+\xi \geq 0& s\in S\\
& \delta \geq \CeT \ye_s+ \CgT\yg_s- \Psi^{\text{cntr}}_s & s\in S\\
&\eqref{val_func:c1}-\eqref{val_func:c4}\\
& \xe,\xg \in \mathbb{Z}^+ \times  \mathbb{R}^+,\ye_s,\yg_s, \xi \in \mathbb{R}\\
& \boldsymbol{\beta}^1, \boldsymbol{\beta}^2,\boldsymbol{\gamma}^1, \boldsymbol{\gamma}^2, \boldsymbol{\pi}^1,\boldsymbol{\pi}^2 \in \mathbb{R}^+
\end{align}
\end{subequations}
