\subsection{Proof of Proposition \ref{prop3}}


Based on the ambiguity set defined in model \eqref{model:wass}, the inner maximization term becomes
\begin{align}
    \max_{\mathbb{P}\in \mathcal{P}(\mathbb{Q}, \mathfrak{D})} &\sum_{i\in \mathcal{M}}p_i V(x,\omega)\\
    \text{s.t.}\ & W_L(\mathbb{P},\mathbb{Q}) \leq \mathfrak{D}
\end{align}

\noindent or equivalently

\begin{subequations}
    \begin{align}
    \max_{\mathbb{P}\in \mathcal{P}(\mathcal{S})} &\sum_{i\in \mathcal{M}}p_i V(x,\omega_i)\\
    \text{s.t.}\ & \sum_{j\in \mathcal{K}}\sum_{i\in \mathcal{M}} ||\omega_i-\zeta_j||^L \pi_{ij} \leq \mathfrak{D} & \label{wass3-c1}\\
    & \sum_{j\in \mathcal{K}} \pi_{ij}-p_i = 0 & i\in \mathcal{M} \label{wass3-c2} \\\
    & \sum_{i\in \mathcal{M}} \pi_{ij} = q_j & j \in \mathcal{K}\ \label{wass3-c3}  \\
    & \sum_{i\in \mathcal{M}} p_i =1& \label{wass3-c4} \\
    &\pi_{ij}, p_i\in \mathbb{R}^+
\end{align}
\end{subequations}

Based on constraints \eqref{wass3-c2}, $p_i$ can be eliminated to achieve
\begin{subequations}\label{model:wass-model1}
    \begin{align}
    \max_{\mathbb{P}\in \mathcal{P}(\mathcal{S})} &\sum_{i\in \mathcal{M}}\sum_{j\in \mathcal{K}} \pi_{ij} V(x,\omega_i)\\
    \text{s.t.}\ & \sum_{j\in \mathcal{K}}\sum_{i\in \mathcal{M}} ||\omega_i-\zeta_j||^L \pi_{ij} \leq \mathfrak{D} & \ [\beta^1]\\
    & \sum_{i\in \mathcal{M}} \pi_{ij} = q_j & j \in \mathcal{K}\ [\beta^2_j]\\
    &\pi_{ij}\in \mathbb{R}^+
\end{align}
\end{subequations}

{Note that constraint~\eqref{wass3-c4} is no longer needed because $\sum_{i,j}\pi_{ij}$ becomes equal to $\sum_{j}q_j$ according to constraints~\eqref{wass3-c3} which is equal to 1 by definition.}
The dual of model \eqref{model:wass-model1} is
\begin{subequations}\label{model:wass-expect}
    \begin{align}
        \min \ &\ \mathfrak{D}\beta^1+\sum_{j\in \mathcal{K}} \beta^2_j q_j\\
     \text{s.t.}\  & ||\omega_i-\zeta_j||^L \beta^1 + \beta^2_j \geq V(x,\omega_i) & i\in \mathcal{M}, j\in \mathcal{K} \label{wass-c1}\\
       & \beta^1\in \mathbb{R}^+, \beta^2_i \in \mathbb{R} \label{wass-c2}
    \end{align}
\end{subequations}

Applying the same procedure, the second minimization term (i.e., risk term) becomes

\begin{subequations}\label{model:wass-cvar}
    \begin{align}
        \min \ &\ \eta+\frac{1}{1-\alpha}(\mathfrak{D}\beta^1+\sum_{j\in \mathcal{K}} \beta^2_j q_j)\\
     \text{s.t.}\ & ||\omega_i-\zeta_j||^L \beta^1 + \beta^2_j  \geq V(x,\omega_i)-\eta& i\in \mathcal{M}, j \in \mathcal{K} \label{wass2-c2} \\
       & ||\omega_i-\zeta_j||^L \beta^1 + \beta^2_j  \geq  0 & i\in \mathcal{M}, j \in \mathcal{K}   \label{wass2-c3}
    \end{align}
\end{subequations}


Replacing the expectation and risk terms from models \eqref{model:wass-expect} and \eqref{model:wass-cvar} in the original formulation gives us

\begin{subequations}
    \begin{align}
        \min \ &\ \CeO \xe + \CgO \xg+\lambda (\mathfrak{D}\beta^1+\sum_{j\in \mathcal{K}} \beta^2_j q_j)+ \notag \\
        & (1-\lambda)\left[\frac{1}{1-\alpha}( \mathfrak{D}\beta^1+\sum_{j\in \mathcal{K}} \beta^2_j q_j) +\eta \right] \notag \\     
      \text{s.t.}\ & \eqref{wass-c1}, \eqref{wass-c2}, \eqref{wass2-c2}, \eqref{wass2-c3}, \eqref{val_func:c1}-\eqref{val_func:c4} \\
      & \xe,\xg \in \mathbb{Z}^+ \times \mathbb{R}^+,\ye_i,\yg_i \in \mathbb{R}^+
    \end{align}
\end{subequations}

\noindent which is equivalent to the following MILP:
\begin{subequations}
    \begin{align}
        \min \ &\ \CeO \xe + \CgO \xg+\lambda (\mathfrak{D}\beta^1+\sum_{j\in \mathcal{K}} \beta^2_j q_j)+ \notag \\
        & (1-\lambda)\left[\frac{1}{1-\alpha}( \mathfrak{D}\beta^1+\sum_{j\in \mathcal{K}} \beta^2_j q_j) +\eta \right] \notag \\   
      \text{s.t.}\ & ||\omega_i-\zeta_j||^L \beta^1 + \beta^2_j  \geq V(x,\omega_i)& i\in \mathcal{M}, j\in \mathcal{K}\\
      & ||\omega_i-\zeta_j||^L \beta^1 + \beta^2_j  \geq V(x,\omega_i)-\eta& i\in \mathcal{M}, j\in \mathcal{K}\\
      % & \delta^2 \geq \delta^1_j-\beta^2_j& j\in \mathcal{K}\\
      & ||\omega_i-\zeta_j||^L \beta^1 + \beta^2_j  \geq  0 & i\in \mathcal{M}, j \in \mathcal{K}\\
      & \BeO\ye_i+\AeO\xe=\de_i & i\in \mathcal{M} \\
& \BeT\ye_i+\Fv_i\AeT\xe=\bT & \nu \in \mathcal{V},i\in \mathcal{M} \\
&\BgO\yg_i+\AgO\xg=\dg_s & i\in \mathcal{M}\\
& \Be\ye_i+\Bg\yg_i+\Ae\xe+\Ag\xg=\bb & i\in \mathcal{M} \\
      &\xe,\xg \in \mathbb{Z}^+ \times \mathbb{R}^+,\ye_i,\yg_i, \beta^1\in \mathbb{R}^+, \beta^2_i,\delta^1_j, \delta^2 \in \mathbb{R}
    \end{align}
\end{subequations}


\section{SP Model} \label{App-sec:SP-model}
Let the uncertain power demand, capacity factors of VREs, and gas demand have a  probability distribution $\mathbb{P}$ with finite and discrete support $\Xi=\{\xi^1, \xi^2,\ldots, \xi^S \}$ where $\mathbb{P}(\xi^s)=p_s$ for all $s\in \mathcal{S}=\{1,2,\ldots, S\}$. 
Let $\de_s$, $\Fv_s$, and $\dg_s$ to denote the power demand, capacity factors of VREs, and gas demand for scenario $s$. Also let $\xeg=(\xe,\xg)$ and $\boldsymbol{\omega}_s =(\de_s,\dg_s,\Fv_s)$ to simplify the exposition.
Then, the two-stage stochastic programming model with a mean-CVaR objective for the joint power-gas planning is formulated as:


\begin{align}\label{model:sp_orig}
\min_{x\in \mathcal{X}} \ & \CeO \xe + \CgO \xg +\lambda \mathbb{E}_{\mathbb{P}}[V(\xeg,\boldsymbol{\omega}_s)]+(1-\lambda)\cvar^\alpha_{\mathbb{P}}(V(\xeg,\boldsymbol{\omega}_s))
\end{align}
% where, for a feasible $x\in \mathcal{X}$ and scenario $s\in \mathcal{S}$, $V(\xeg,\boldsymbol{\omega}_s)$ is defined as:

% \begin{subequations}\label{model:val_func}
% \begin{align}
% V(\xeg,\boldsymbol{\omega}_s)= \min \ & \CeT \ye_s+ \CgT\yg_s \\
% \text{s.t. }\ & \BeO\ye_s=\de_s-\AeO\xe \\
% & \BeT\ye_s=\bT-\Fv_s\AeT\xe & \nu \in \mathcal{V} \\
% &\BgO\yg_s=\dg_s-\AgO\xg \\
% & \Be\ye_s+\Bg\yg_s=\bb-\Ae\xe-\Ag\xg 
% \end{align}
% \end{subequations}

% Where \cvar{} is a risk measure function defined as \citep{SarykalinEtal2008_CVaR_VaR}:
% $$
% \cvar^\alpha_{\mathbb{P}}(V(\xeg,\boldsymbol{\omega}_s)) =\min_{\eta\in \mathbb{R}} \{\eta +\frac{1}{1-\alpha}\mathbb{E}_{\mathbb{P}}[\max(V(\xeg,\boldsymbol{\omega}_s)-\eta,0)] \} 
% $$

% \cvar{} quantifies the potential loss in the worst $(1-\alpha)\%$ of the uncertain parameters' realization (scenarios). The optimum value of CVaR is attained at the confidence level $\alpha \in [0,1)$ is referred to as \textit{value-at-risk (VaR)} \citep{SarykalinEtal2008_CVaR_VaR}. 
\noindent where in the case of stochastic programming with discrete scenarios, the \cvar can equivalently be formulated as:

$$
\cvar^\alpha_{\mathbb{P}}(V(\xeg,\boldsymbol{\omega}_s)) =\min_{\eta\in \mathbb{R}} \{\eta+\frac{1}{1-\alpha}\sum_{s\in \mathcal{S}}p_sV_s: V_s\geq \theta_s-\eta, \quad s\in \mathcal{S}, V_s\in \mathcal{R}^+ \} 
$$

Then the extensive formulation of problem~\eqref{model:sp_orig} becomes:
\begin{subequations}
\begin{align}
\min \ &\CeO \xe+\CgO \xg +\lambda \sum_{s\in \mathcal{S}}p_s\theta_s+(1-\lambda)(\eta+\frac{1}{1-\alpha}\sum_{s\in \mathcal{S}}p_sV_s)\\
\text{s.t. }\ & \AeO\xe+\BeO\ye_s=\de_s & s\in \mathcal{S} \\
& \Fv_s\AeT\xe+\BeT\ye_s=\bT & \nu \in \mathcal{V}, s\in \mathcal{S} \\
&\AgO\xg+\BgO\yg_s=\dg_s & s\in \mathcal{S}\\
& \Ae\xe+\Be\ye_s+\Ag\xg+\Bg\yg_s=\bb & s\in \mathcal{S}\\ 
& \theta_s = \CeT \ye_s+\CgT \yg_s & s\in \mathcal{S}\\
&V_s\geq \theta_s-\eta & s\in \mathcal{S} \\
&\xe,\xg \in \mathbb{Z}^+ \times \mathbb{R}^+,\ye_s,\yg_s,\eta, V_s\in \mathbb{R}^+
\end{align}
\end{subequations}

