\subsection{Mathematical Model}
The SP model's objective function is the summation of model~\eqref{elec-obj} and \eqref{ng-obj}. The constrains of SP consist of constraints presented in models~\eqref{pow-constraints}, \eqref{gas-constraints}, \eqref{coupling-costraints}. 


\noindent\textbf{Power System Objective Function:}
\begin{subequations} \label{elec-obj}
\begin{align}
      \min & \sum_{n \in \mathcal{N}^{\text{e}}}\left[ \sum_{i \in \mathcal{P}}  (C^{\text{inv}}_i x^{\text{est}}_{ni}+C^{\text{fix}}_{i} x^{\text{op}}_{ni} +C^{\text{dec}}_i x^{\text{dec}}_{ni}) + \sum_{r \in \mathcal{S}^{\text{e}}_n}\left((C^{\text{pInv}}_r+C^{\text{pFix}}) y^{\text{eCD}}_{nr} +(C^{\text{EnInv}}_r+C^{\text{EnFix}}) y^{\text{eLev}}_{nr}\right)\right] \notag\\
      &+ \sum_{l\in \mathcal{L}^{\text{e}}}  C^{\text{trans}}_{\ell} z^{\text{eInv}}_\ell \notag +\sum_{\ell \in \mathcal{L}^{\text{e}}:I^{\text{trans}}_\ell=1} C^{\text{trFix}}_\ell +\sum_{\ell \in \mathcal{L}^{\text{e}}:I^{\text{trans}}_\ell=0} C^{\text{trFix}}_\ell z^{\text{eInv}}_\ell  \\  
         &+  \sum_{n \in \mathcal{N}^{\text{e}}}\sum_{t\in \mathcal{T}^{\text{e}}} \left[ w_{ts} C^{\text{eShed}}_n a^{\text{e}}_{nts} + \sum_{i \in \mathcal{P}}w_{ts} p_{ntis} C^{\text{fuel}}_{i} h_i + w_{ts} p_{ntis}C^{\text{var}}_{i}\right]
\end{align}
\end{subequations}

The objective function~\eqref{elec-obj} minimizes the total investment and operating costs incurred in the power system including investment in new power plants, fixed operation and maintenance (FOM) of power plants, decommission of power plants, investment in storage, investment in transmission lines, FOM of transmission lines, load shedding, fuel, and  variable operating and maintenance  (VOM) cost of operating power plants.

\vspace{0.5cm}
\noindent\textbf{Power System Constraints:}
For every $n\in \mathcal{N}^{\text{e}},i\in \mathcal{P}$ $l\in \mathcal{L}^{\text{e}},t \in \mathcal{T}^{\text{e}},  n,m\in \mathcal{N}^{\text{e}}_\ell, r\in \mathcal{S}^{\text{e}}_n, s\in \mathcal{S}$ the constraints are defined as:
\begin{subequations}\label{pow-constraints}
\begin{align}
      & x^{\text{op}}_{ni} = I^{\text{num}}_{ni}-x^{\text{dec}}_{ni}+x^{\text{est}}_{ni} &  \label{elec-c1}\\
        &L^{\text{prod}}_{i} x_{ni} \leq  p_{ntis} \leq   U^{\text{prod}}_{i}x_{ni}&\hspace{-2cm} i\in \mathcal{H} %[\beta_{nti}] 
    \label{elec-c4}\\
    % ramping 
    &| p_{ntis} -p_{n,(t-1),i}| \leq U^{\text{ramp}}_{i}U^{\text{prod}}_{i}x^{ni}   & \hspace{-2cm} i\in \mathcal{H} \label{elec-c5}\\
     &p_{ntis} \leq \rho_{ntis}U^{\text{prod}}_{i} x^{\text{op}}_{ni} &\hspace{-2cm} i \in \mathcal{R}  \label{elec-c6}\\
     & a^{\text{e}}_{nts}\leq D^{\text{e}}_{n\phi^{\text{e}}_{ts}}& \label{elec-c7} \\
      &\sum_{i \in \mathcal{P}}p_{ntis} +\sum_{m\in \mathcal{N}^{\text{e}}}\sum_{l\in \mathcal{L}^{\text{e}}_{nm}}\sign(n-m) f^{\text{e}}_{\ell ts}+\sum_{r\in \mathcal{S}^{\text{e}}_n} (s^{\text{eDis}}_{ntr}-s^{\text{eCh}}_{ntrs})+ a^{\text{e}}_{nts}=D^{\text{e}}_{n \phi^{\text{e}}_{ts}}       \label{elec-c8}   \\
      %% flow constraints
    & \vert f^{\text{e}}_{lt }\vert \leq I^{\text{trans}}_{\ell}&\hspace{-2cm}  \text{if } \mathcal{I}^{\text{trans}}_\ell=1   \label{elec-c9}\\
      & \vert f^{\text{e}}_{lt }\vert \leq U^{\text{trans}}_\ell z^{\text{eInv}}_{\ell}& \hspace{-2cm}  \text{if } \mathcal{I}^{\text{trans}}_\ell=0  \label{elec-c10}\\
      %storage level
      & s^{\text{eLev}}_{n t r}=(1-\gamma^{\text{loss}}_{r}) (s^{\text{eLev}}_{ntr})+ \gamma^{\text{eCh}}_r s^{\text{eCh}}_{ntr}-\frac{s^{\text{eDis}}_{n t r}}{\gamma^{\text{eDis}}_r}& \hspace{-4cm} t\in \mathcal{T}^{\text{e}}\backslash \{t^{\text{start}}_\tau \lvert \  \tau \in \mathfrak{R} \}   \label{elec-c16}\\
      % storage at the first hour
       & s^{\text{eLev}}_{n 0 r}= \gamma^{\text{eCh}}_r s^{\text{eCh}}_{n0 r}-\frac{s^{\text{eDis}}_{n 0 r}}{\gamma^{\text{eDis}}_r}&   \label{elec-c15}\\
    & s^{\text{eCh}}_{ntrs}\leq y^{\text{eCD}}_{nr}, \quad s^{\text{eCh}}_{ntrs}\leq y^{\text{eCD}}_{nr}, \quad s^{\text{eLev}}_{ntr}\leq y^{\text{eLev}}_{nr} &  \label{elec-c21}\\
     & \sum_{n\in \mathcal{N}^{\text{e}}}\sum_{i\in \mathcal{Q}}  U^{\text{prod}}_i x^{\text{op}}_{ni} \leq U^{\text{prod}}_{\mathcal{Q}} & \mathcal{Q}\in \mathcal{Q}'
   \label{elec-c24}
\end{align}
\end{subequations}

Constraints~\eqref{elec-c1} model the number of operating plants. The generation limits are imposed in constraints~\eqref{elec-c4}. 
Constraints~\eqref{elec-c5} are the ramping constraints. The generation pattern of VREs is imposed in constraints~\eqref{elec-c6}. Constraints~\eqref{elec-c7} state that the load-shedding amount can not exceed demand. Constraints~\eqref{elec-c8} ensure the power balance. Flow for the existing transmission lines is limited by constraints~\eqref{elec-c9}. Constraints~\eqref{elec-c10} limit the flow in candidate transmission lines only if it is already established (i.e., $z^{\text{t}}_{\ell}$=1). 
Constraints~\eqref{elec-c16}-\eqref{elec-c21} model battery storage dynamics and storage limit. Finally, constraint~\eqref{elec-c24} limits the installed capacity of a certain set of power plants to their maximum availability limit. 


\noindent\textbf{Gas System Objective Function:} 
\begin{subequations}\label{ng-obj}
\begin{align}
    \min & \sum_{l\in \mathcal{L}^{\text{g}}} \left (C^{\text{pipe}}_{\ell} z_{\ell}^{\text{g}} + c^{\text{pipeDec}}_\ell z^{\text{gDec}}\ell + c^{\text{pipeFix}}_\ell z^{\text{gOp}}_\ell \right)  \\
    &+ \sum_{k \in \mathcal{N}^{\text{g}}} \sum_{\tau \in \mathcal{T}^{\text{g}}}  C^{\text{ng}} g_{k\tau} + C^{\text{gShed}} a^{\text{ng}}_{k\tau }\\
    &+ \sum_{j \in \mathcal{N}^s}(C^{\text{strInv}}_j x^{\text{gStr}}_{j} +C^{\text{vprInv}}_j x^{\text{vpr}}_{j}) +C^{\text{strFix}}(I^{\text{gStr}}_{j}+x^{\text{gStr}}_j)+C^{\text{vprFix}}(I^{\text{vpr}}_{j}+x^{\text{vpr}}_j)\\
\end{align}
\end{subequations}

The objective function~\eqref{ng-obj} minimizes the total investment and operating costs incurred in the gas system including investment/decommissioning/FOM of pipelines, import, load shedding, and storage/vaporization/liquefaction costs. 

\vspace{0.5cm}
\noindent\textbf{Gas System Constraints:} 
For every $k\in \mathcal{N}^{\text{g}}, \tau \in \mathcal{T}^{\text{g}} $ $\ell \in \mathcal{L}^{\text{g}}, j\in \mathcal{N}^s, s\in \mathcal{S}$

\begin{subequations}\label{gas-constraints}
\begin{align}
   &g_{k\tau} -\sum_{l \in \mathcal{L}^{\text{gExp}}_{k}} f^{\text{g}}_{\ell\tau s}+\sum_{l \in \mathcal{L}^{\text{gImp}}_{k}} f^{\text{g}}_{\ell\tau s}-\sum_{n\in \mathcal{A}^{\text{e}}_k} f^{\text{ge}}_{kn\tau } +\sum_{j\in \mathcal{A}^s_k} (f^{\text{vg}}_{jk \tau}-f^{\text{gl}}_{kj\tau s})+ a^{\text{LCF}}_{k\tau}+a^{\text{g}}_{k\tau s}=D^{\text{g}}_{k\tau s} &  \label{ng-c1}\\
& L^{\text{inj}}_k \leq g_{k\tau}+a^{\text{LCF}}_{k\tau}\leq U^{\text{inj}}_k & \label{ng-c2}\\
& f^{\text{g}}_{\ell \tau } \leq U^{\text{pipe}}_{\ell} z^{\text{gOp}}_{\ell}&  \label{ng-c6}\\
    &\sum_{k \in \mathcal{N}^{\text{g}}:j\in \mathcal{A}^s_k} f^{\text{gl}}_{kj \tau} =s^{\text{liq}}_{j\tau s} & \label{ng-c7}\\
    &\sum_{k \in \mathcal{N}^{\text{g}}:j\in \mathcal{A}^s_k } f^{\text{vg}}_{jk \tau}=s^{\text{vpr}}_{j\tau s}  & \label{ng-c8}\\
     &s^{\text{gStr}}_{j\tau s} = (1-\beta) s^{\text{gStr}}_{j,\tau-1}+\gamma^{\text{liqCh}}_j s^{\text{liq}}_{j\tau s}-\frac{s^{\text{vpr}}_{j\tau s}}{\gamma^{\text{vprDis}}_j}  &  \label{ng-c9}\\
   %% Storage limit
    &s^{\text{vpr}}_{j\tau s}\leq  I^{\text{vpr}}_{j}+x^{\text{vpr}}_j  &  \label{ng-c10}\\
    &s^{\text{gStr}}_{j\tau s}\leq  I^{\text{gStr}}_{j}+x^{\text{gStr}}_j  &  \label{ng-c11}\\
    &z^{\text{gOp}}_\ell =  \mathcal{I}^{\text{pipe}} + z^{\text{gInv}}_\ell - z^{\text{gDec}}_\ell  &  \label{ng-c12}
\end{align}
\end{subequations}
Constraints~\eqref{ng-c1} ensure the gas balance.
The gas fuel import limits are imposed in constraints~\eqref{ng-c2}. 
The constraints~\eqref{ng-c6}  limit the flow between gas nodes for operational pipelines, respectively. The flow to liquefaction facilities is calculated in constraints~\eqref{ng-c7}. Similarly, the flow out of vaporization facilities is modeled via constraints~\eqref{ng-c8}.
Constraints~\eqref{ng-c9} ensure the storage balance. Constraints~\eqref{ng-c10} and \eqref{ng-c11} limit the capacity of vaporization and storage tanks to their initial capacity plus the increased capacity, respectively.
Pipeline $\ell$ is operational if either it is existing and not decommissioned, or newly established. 

\vspace{0.5cm}

\noindent \textbf{Coupling Constraints}
The following constraints are coupling constraints that relate operational decisions of the power and gas systems together.
\begin{subequations}\label{coupling-costraints}
\begin{align}
    & \sum_{k \in \mathcal{A}^{\text{e}}_n} f^{\text{ge}}_{k n\tau } =   \sum_{t \in \mathfrak{T}^{\text{e}}_\tau} \sum_{i \in \mathcal{G}} h_i p_{ntis} &\hspace{-2cm} n\in \mathcal{N}^{\text{e}}, \tau \in \mathfrak{R}\label{coup-1}\\
 &\mathcal{E}^{\text{e}}_s = \sum_{n\in \mathcal{N}^{\text{e}}}\sum_{t\in \mathcal{T}^e}\sum_{i \in \mathcal{G}} w_{ts}(1-\eta_i)\eta^{\text{g}} h_i p_{ntis}&\notag \\
 &\mathcal{E}^{\text{g}}_s =\sum_{k \in \mathcal{N}^g}\sum_{\tau \in \mathcal{T}^g} \eta^{\text{g}}( D^{\text{g}}_{k\tau s}-  a^{\text{LCF}}_{k\tau}-a^{\text{g}}_{k\tau s})\notag \\
 &  \mathcal{E}^{\text{e}}_s+\mathcal{E}^{\text{g}}_s \leq (1-\zeta) (U^{\text{e}}_{\text{emis}} +U^{\text{g}}_{\text{emis}}) &\label{coup-2}
\end{align}
\end{subequations}
The first coupling constraints~\eqref{coup-1} capture the flow of gas to the power network for each node and at each time period. 
The variable $\mathcal{E}^{\text{e}}_s$ accounts for CO$_2$ emission due to the consumption of gas in the power system. The variable  $\mathcal{E}^{\text{g}}_s$ computes the emission from the gas system by subtracting the demand from LCF consumption and gas load shedding. The second coupling constraint~\eqref{coup-2} ensures that the net CO$_2$ emissions associated with the power-gas system are below a pre-specified threshold value, which is defined based on a baseline (e.g., historical) emissions level. The first term is the emissions due to non-power gas consumption (i.e., gas consumption in the gas system such as space heating, industry use, and transportation). Since the model does not track whether LCF is used to meet non-power gas demand or for power generation, the first term computes gross emissions from all gas use presuming it is all fossil and then subtracts emissions benefits from using LCF.

\section{Sequential Construction Method for the Stochastic Program} \label{SCM4SP}
This section details the Sequential Construction Method (SCM) for the model presented in section~\eqref{model-sp}. 

\begin{enumerate}
\item Solve {\textit{MILP}$^{\text{ref}}$} with the following simplifications and get the solution $\bar{X}$:
\begin{itemize}
\item Remove all network constraints for the power system and get the \textit{copper-plate model}. In effect, the constrains (2g) and (2h) are removed from the model presented in section~\eqref{model-sp}, and the constraint (2f) becomes the following for all $t\in \mathcal{T}^{\text{e}}$
$$
\sum_{n\in \mathcal{N}^{\text{e}}}\left[\sum_{i \in \mathcal{P}}p_{ntis} +\sum_{r\in \mathcal{S}^{\text{e}}_n} (s^{\text{eDis}}_{ntr}-s^{\text{eCh}}_{ntrs})+ a^{\text{e}}_{nts}\right]=\sum_{n\in \mathcal{N}^{\text{e}}} D^{\text{e}}_{n \phi^{\text{e}}_{ts}}
$$

\item Relax the integrality of integer variables $x^{\text{op}}_{ni}, x^{\text{est}}_{ni}, x^{\text{dec}}_{ni}, z^{\text{elnv}}_\ell, z^{\text{glnv}}_\ell, z^{\text{gDec}}_\ell, z^{\text{gOp}}_\ell$
\end{itemize}
\item Solve {\textit{MILP}$^{\text{ref}}$} with the following simplifications and constraints and get the solution $\hat{X}$:
\begin{itemize}
\item Relax the integrality of integer variables $x^{\text{op}}_{ni}, x^{\text{est}}_{ni}, x^{\text{dec}}_{ni}, z^{\text{elnv}}_\ell, z^{\text{glnv}}_\ell, z^{\text{gDec}}_\ell, z^{\text{gOp}}_\ell$
\item For thermal plants, set $x^{\text{op}}_{ni} = \lfloor(\bar{x}^{\text{op}}_{ni}) \rceil, n\in\mathcal{N}, i\in \mathcal{H}$, where $\lfloor x \rceil$ is the rounding operator that returns the nearest integer value to $x$, and $\bar{x}^{\text{op}}_{ni}$ is the value of the variable in previous step
\item For VRE plants, add constraints $x^{\text{op}}_{ni} = \lfloor\bar{x}^{\text{op}}_{ni} \rfloor, n\in\mathcal{N}, i\in \mathcal{V}$, where $\lfloor x \rfloor$ is the floor operator that returns the greatest integer less than or equal to $x$, and $\bar{x}^{\text{op}}_{ni}$ is the value of the variable in previous step.
\item Add constraints $z^{\text{gOp}}_\ell=1$ if $\bar{z}^{\text{gOp}}_\ell \geq \epsilon_1$, and $z^{\text{gOp}}_\ell=0$, otherwise.  $\bar{z}^{\text{gOp}}_\ell$ is the value of the variable in previous step
\end{itemize}
\item Solve {\textit{MILP}$^{\text{ref}}$} with the following simplifications and constraints and get feasible solution ${{X}}^*$:
\begin{itemize}
\item Set $x^{\text{op}}_{ni} = \hat{x}^{\text{op}}_{ni}, n\in\mathcal{N}, i\in \mathcal{H}$, where $\hat{x}^{\text{op}}_{ni} $ is the value of the variable in previous step.
\item Set $z^{\text{gOp}}_\ell =  \hat{z}^{\text{gOp}}_\ell$, where $\hat{z}^{\text{gOp}}_\ell$  is the value of the variable in previous step.
\item Add constraints $z^{\text{eInv}}_\ell=1$ if $\hat{z}^{\text{eInv}}_\ell > \epsilon_2$, and $z^{\text{eInv}}_\ell=0$, otherwise. $\hat{z}^{\text{eInv}}_\ell$ is the value of the variable in previous step.
\end{itemize}
\end{enumerate}
In our experiments, $\epsilon_1=0.01 $ and $\epsilon_2=0.3$. 


