        \STATE $//$ Local training process for global model;
        \FOR {$n \in \mathbb{N}$}
        \STATE Obtain $\boldsymbol{\omega}^{t}$ and let $\boldsymbol{u}_{n}^{t}=\boldsymbol{\omega}^{t}$ ;
	\STATE Update the local model: 
        % \STATE 
        $\boldsymbol{u}_{n}^{t+1}=\boldsymbol{u}_{n}^{t}-\eta_{\mathrm{G}}\nabla F_{n}(\boldsymbol{u}_{n}^{t})$.
        \STATE Clip the local model:
        % \STATE 
        $\boldsymbol{u}_{n}^{t+1}=\boldsymbol{u}_{n}^{t+1}/\max(1,\frac{\parallel \boldsymbol{u}_{n}^{t+1}\parallel}{C})$;
        \STATE Add noise and upload:
        % \STATE 
        $\overset{\sim}{\boldsymbol{u}}_{n}^{t+1}=\boldsymbol{u}_{n}^{t+1}+\mathbf{z}_{n}^{t+1}$

        \STATE $//$ Local training process for personalized model;
        \STATE Update personalized model $\boldsymbol{\varpi}_{n}^{t+1}$ :
        \STATE $\boldsymbol{\varpi}_{n}^{t+1}=\boldsymbol{\varpi}_{n}^{t}-\eta_{\mathrm{L}}(\left(1-\frac{\lambda}{2}\right)\nabla F_{n}(\boldsymbol{\varpi}_{n}^{t})+\lambda(\boldsymbol{\varpi}_{n}^{t}-\boldsymbol{\omega}^{t}))$;
        \ENDFOR
        \STATE $//$ Global model aggregating process;
        \STATE Update the global model:
        % \STATE 
        $\overset{\sim}{\boldsymbol{\omega}}^{t+1}=\frac{1}{N}{\sum}_{n=1}^{N}\overset{\sim}{\boldsymbol{u}}_{n}^{t+1}$;
        \ENDFOR
	\end{algorithmic}
	\end{algorithm}


