\section{Convergence of Privacy-Preserving PFL
}

This section establishes the convergence upper bound of PFL 
and optimizes the number $T$ of aggregation rounds to minimize the convergence upper bound of PL. 
The following assumptions facilitate the convergence analysis of {PFL}.
\begin{assumption}
\label{assumption1}
$\forall n \in \mathbb{N}$, 
\begin{itemize}
    \item 
$F_{n}\left(\cdot\right)$ is $\mu$-strongly convex \cite{karimi2016linear,10123399,10542235} and $L$-smooth \cite{o2006metric,10123399,10542235}, i.e., $F\left(\boldsymbol{\omega}\right)-F\left(\boldsymbol{\omega}^{\ast}\right)\leq\frac{1}{2\mu}\parallel\nabla F\left(\boldsymbol{\omega}\right)\parallel^{2}$ and $\parallel\nabla F\left(\boldsymbol{\omega}\right)-\nabla F\left(\boldsymbol{\omega}'\right)\parallel\leq L\parallel\boldsymbol{\omega}-\boldsymbol{\omega}'\parallel$. Here, $\mu$ and $L$ are constants;
\item 
The global learning rate $\eta_{\mathrm{G}}\leq\frac{2}{L}$, and $\mu>\frac{2-2\lambda}{2-\lambda}$;
\item 
$\mathbb{E}\left[\parallel\nabla F_{n}(\boldsymbol{\omega}^{t})\parallel^{2}\right]\leq G_{0}^{2}$ {with $G_{0}$ being a constant.};
\item 
$\parallel \boldsymbol{u}_{n}^{\ast}-\boldsymbol{\omega}^{\ast}\parallel\leq M$, where $M$ is a constant.

\end{itemize}
\end{assumption}


\subsection{Convergence Analysis}
\subsubsection{Convergence of FL}
The convergence upper bound of FL with DP has been established in the literature \cite[Eq.~(16)]{wei2020federated} 
    	\begin{equation} 
	%\begin{split}
        \label{gloCon}
\mathbb{E}\left[F\left(\overset{\sim}{\boldsymbol{\omega}}^{T}\right)-F\left({\boldsymbol{\omega}}^{\ast}\right)\right]\leq \varepsilon_{\mathrm{G}}^T \Psi_{1}
+(1-\varepsilon_{\mathrm{G}}^T)\frac{\varphi T}{N\epsilon^2}
        \,,
	%\end{split}
	\end{equation}
where, for conciseness, $\varepsilon_{\mathrm{G}}=1-2\mu\eta_{\mathrm{G}}+\mu\eta_{\mathrm{G}}^{2}L$, $\Psi_{1}=F\left(\boldsymbol{\omega}^{0}\right)-F\left(\boldsymbol{\omega}^{\ast}\right)$, and $\varphi=\frac{L^2 \Delta s^{2} \ln\left(1/\delta\right)}{\mu}$. 
Clearly, 
% According to (\ref{gloCon}), 
the DP noise increases the convergence upper bound with $\varphi=\frac{L^2\sigma_z^2}{2T}$.

\subsubsection{Convergence of PL}
Under \textbf{Assumption \ref{assumption1}}, the convergence upper bound of PL is established in
 the following. 
\begin{lemma}
\label{Lemma1}
Given the PL rate $\eta_{\mathrm{L}}$ and the weighting coefficient $\lambda$, under \textbf{Assumption \ref{assumption1}}, the expected difference between the personalized model $\overset{\sim}{\boldsymbol{\varpi}}_n^{t+1}$ and the optimum $\boldsymbol{\varpi}_n^{\ast}$ 
at the end of the $t$-th communication round is upper-bounded by
       \begin{equation} 
	\begin{split}
        \label{PerOneStep2_l}
&\mathbb{E}\left[\parallel\overset{\sim}{\boldsymbol{\varpi}}_{n}^{t+1}-\boldsymbol{\varpi}_{n}^{\ast}\parallel^{2}\right]
\leq \varepsilon_{\mathrm{L}}\mathbb{E}\left[\parallel\overset{\sim}{\boldsymbol{\varpi}}_{n}^{t}-\boldsymbol{\varpi}_{n}^{\ast}\parallel^{2}\right]+\\
&\left(\eta_{\mathrm{L}}^{2}+\eta_{\mathrm{L}}^{2}\lambda^{2}\right)G+\frac{4\eta_{\mathrm{L}}^{2}\lambda^{2}\!\!+\!\!2\eta_{\mathrm{L}}\lambda^{2}}{\mu}\mathbb{E}\!\!\left[F\!\left(\overset{\sim}{\boldsymbol{\omega}}^{t}\right)\!\!-\!\!F\!\left(\boldsymbol{\omega}^{\ast}\right)\right]
        \,,
	\end{split}
	\end{equation}
where {$G \triangleq \left(\!\left(1\!-\!\frac{\lambda}{2}\right)G_{0}\!+\!\lambda\left(\frac{G_{0}}{\mu}\!+\!M\right)\!\right)^{2}$,} and $\varepsilon_{\mathrm{L}}\!=\!1\!-\!\eta_{\mathrm{L}}\!\left(\!\left(1\!-\!\frac{\lambda}{2}\right)\!\mu\!+\!\lambda\right)\!+\!\eta_{\mathrm{L}}$. Clearly, $\varepsilon_{\mathrm{L}}$ increases with $\lambda$ when $\mu > 2$. 
\end{lemma}

\begin{proof}    See \textbf{Appendix \ref{pLemma1}}.
\end{proof}

\vspace{2 mm}
\textbf{Lemma \ref{Lemma1}} can be verified in two special cases. 
One is that PFL is only executed locally ($\lambda=0$). By \textbf{Lemma \ref{Lemma1}}, we have
         \begin{equation} 
         %\begin{split}
        \label{peronestep_lambda0}
        \mathbb{E}\left[\parallel\overset{\sim}{\boldsymbol{\varpi}}_{n}^{t+1}-\boldsymbol{\varpi}_{n}^{\ast}\parallel^{2}\right]
        \leq \varepsilon_{\mathrm{L}}\mathbb{E}\left[\parallel\overset{\sim}{\boldsymbol{\varpi}}_{n}^{t}-\boldsymbol{\varpi}_{n}^{\ast}\parallel^{2}\right]+\eta_{\mathrm{L}}^{2}G
        \,,
        %\end{split}
	\end{equation}
which depends only on the FL local training. The obtained personalized models are obviously unaffected by the DP noise.

Another special case involves no PL, i.e., $\lambda=2$. Then, $\boldsymbol{\varpi}_{n}^{\ast}=\underset{\boldsymbol{\varpi}_{n}}{\arg\min}\,\parallel\boldsymbol{\varpi}_{n}-\boldsymbol{\omega}^{\ast}\parallel^{2}$, i.e., $\boldsymbol{\varpi}_{n}^{\ast}=\boldsymbol{\omega}^{\ast}$. Hence,
% and it readily follows that 
{\small
         \begin{subequations} 
         \begin{align}
        \label{peronestep_lambda2_1}
        \begin{split}
       \mathbb{E} &\bigg[\parallel\overset{\sim}{\boldsymbol{\varpi}}_{n}^{t+1}-\boldsymbol{\omega}^{\ast}\parallel^{2}\bigg]
        \leq  \varepsilon_{\mathrm{L}}\mathbb{E}\left[\parallel\overset{\sim}{\boldsymbol{\varpi}}_{n}^{t}-\boldsymbol{\omega}^{\ast}\parallel^{2}\right]+5\eta_{\mathrm{L}}^{2}G\\
        &+\frac{16\eta_{\mathrm{L}}^{2}+8\eta_{\mathrm{L}}}{\mu}\mathbb{E}\left[F\left(\overset{\sim}{\boldsymbol{\omega}}^{t}\right)-F\left(\boldsymbol{\omega}^{\ast}\right)\right] 
        \end{split} \\
        \label{peronestep_lambda2_3}
        \begin{split}
        % = 
        &\leq \!
        (\varepsilon_{\mathrm{L}}\!\!+\!\!5\eta_{\mathrm{L}}^{2}) (\frac{G_{0}}{\mu}\!+\!M)^{2}\!\!+\!\!\frac{16\eta_{\mathrm{L}}^{2}\!\!+\!\!8\eta_{\mathrm{L}}}{\mu}\mathbb{E}\!\left[\!F\!\left(\overset{\sim}{\boldsymbol{\omega}}^{t}\right)\!\!-\!\!F\!\left(\boldsymbol{\omega}^{\ast}\right)\!\right],
        \end{split}       
        \end{align}
	\end{subequations} %
 }%
where (\ref{peronestep_lambda2_3}) is obtained by substituting (\ref{E2}) into (\ref{peronestep_lambda2_1}). 
As revealed in (\ref{peronestep_lambda2_3}), the convergence of PL depends only on the FL and hence the DP in PFL.

\begin{lemma}
\label{lemma2}
Given $F\left(\boldsymbol{\omega}\right)-F\left(\boldsymbol{\omega}^{\ast}\right)\leq\frac{1}{2\mu}\parallel\nabla F\left(\boldsymbol{\omega}\right)\parallel^{2}$ under \textbf{Assumption 1}, the expectation of the difference between the FL model in the $t$-th communication round, i.e., $\overset{\sim}{\boldsymbol{\omega}}^{t+1}$, and the optimal global model $\boldsymbol{\omega}^{\ast}$ is upper bounded by 
    {\small
    \begin{equation} 
	% \begin{split}
        \label{gloOneStep}
\mathbb{E}\left[F(\overset{\sim}{\boldsymbol{\omega}}^{t+1})-F\left(\boldsymbol{\omega}^{\ast}\right)\right]\leq\!{\varepsilon_{\mathrm{G}}}\mathbb{E}\left[F(\overset{\sim}{\boldsymbol{\omega}}^{t})\!-\!F\left(\boldsymbol{\omega}^{\ast}\right)\right]\!+\!
\varphi_{\mathrm{L}} {T},
	% \end{split}
	\end{equation}
 }%
 {where $\varphi_{\mathrm{L}}=\sigma_z^2\frac{dL}{2TN^2}=\frac{\Delta s^{2}Ld\ln\left(1/\delta\right)}{N^2\epsilon^{2}}$ based on~\eqref{noiseSigma1}.}
\end{lemma}

\begin{proof}
    See \textbf{Appendix \ref{plemma2}}.
\end{proof}

\begin{theorem}
\label{con_UpperBound}
Under \textbf{Assumption \ref{assumption1}},
the convergence upper bound of PL after $T$ aggregation rounds is given as follows:

When $\varepsilon_{\mathrm{L}} \neq \varepsilon_{\mathrm{G}}$,
{\small
         \begin{equation} 
	\begin{split}
        \label{theoConverT}
&\mathbb{E}\left[\parallel\overset{\sim}{\boldsymbol{\varpi}}_{n}^{T}-\boldsymbol{\varpi}_{n}^{\ast}\parallel^{2}\right]
\leq \varepsilon_{\mathrm{L}}^{T}\Psi_{2}+\left(1+\lambda^{2}\right)\eta_{\mathrm{L}}^{2}G\frac{\varepsilon_{\mathrm{L}}^{T}-1}{\varepsilon_{\mathrm{L}}-1}\\
&+\!\!\frac{(4\eta_{\mathrm{L}}^{2}\!\!+\!\!2\eta_{\mathrm{L}})\lambda^{2}}{\mu}\!\!\left[\!\frac{\varepsilon_{\mathrm{L}}^{T}\!\!-\!\!\varepsilon_{\mathrm{G}}^{T}}{\varepsilon_{\mathrm{L}}\!\!-\!\!\varepsilon_{\mathrm{G}}}\Psi_{1}\!\!+\!\!\left(\!\!\frac{\varepsilon_{\mathrm{L}}^{T\!-\!1}\!\!-\!\!\varepsilon_{\mathrm{G}}^{T\!-\!1}}{\frac{\varepsilon_{\mathrm{L}}}{\varepsilon_{\mathrm{G}}}-1}\!\!-\!\!\frac{\varepsilon_{\mathrm{L}}^{T\!-\!1}\!\!-\!\!1}{\varepsilon_{\mathrm{L}}\!\!-\!\!1}\!\!\right)\!\!\frac{\varphi_{\mathrm{L}}T}{\varepsilon_{\mathrm{G}}\!\!-\!\!1}\!\right];
	\end{split}
	\end{equation}
 }


When $\varepsilon_{\mathrm{L}} = \varepsilon_{\mathrm{G}}$,
{\small
         \begin{equation} 
	\begin{split}
        \label{theoConverT_LG}
&\mathbb{E}\left[\parallel\overset{\sim}{\boldsymbol{\varpi}}_{n}^{T}-\boldsymbol{\varpi}_{n}^{\ast}\parallel^{2}\right]
\leq \varepsilon_{\mathrm{L}}^{T}\Psi_{2}+\left(1+\lambda^{2}\right)\eta_{\mathrm{L}}^{2}G\frac{\varepsilon_{\mathrm{L}}^{T}-1}{\varepsilon_{\mathrm{L}}-1}\\
&+\!\frac{(4\eta_{\mathrm{L}}^{2}\!\!+\!\!2\eta_{\mathrm{L}})\lambda^{2}}{\mu}\!\!\left[\!T\varepsilon_{\mathrm{L}}^{T\!-\!1}\Psi_1 \!\!+\!\!\left(\!(T\!\!-\!\!1)\varepsilon_{\mathrm{L}}^{T\!-\!1}\!\!-\!\!\frac{\varepsilon_{\mathrm{L}}^{T\!-\!1}\!-\!1}{\varepsilon_{\mathrm{L}}\!\!-\!\!1}\right)\!\frac{{\varphi_{\mathrm{L}}}T}{\varepsilon_{\mathrm{L}}\!\!-\!\!1}\!\right],
	\end{split}
	\end{equation} %
 }%
where, for conciseness, $\Psi_{2}=\parallel\boldsymbol{\varpi}_{n}^{0}-\boldsymbol{\varpi}_{n}^{\ast}\parallel^{2}$.

\end{theorem}

\begin{proof}
    See \textbf{Appendix \ref{pcon_UpperBound}}.
\end{proof}

\vspace{2 mm}
A trade-off between convergence and privacy is revealed in {(\ref{theoConverT})  and (\ref{theoConverT_LG})}: 
As the DP noise variance $\sigma_z^2$ increases, the convergence upper bound of PL increases since the term resulting from the DP noise is positive {since $\varphi_{\mathrm{L}}>0$ and $\sum_{x=0}^{t-1}\sum_{y=0}^{t-1-x}\varepsilon_{\mathrm{L}}^{x}\varepsilon_{\mathrm{G}}^{y}>0$ in the bound.} 
Moreover, the convergence upper bound of PL depends on $\lambda$. A larger $\lambda$ leads to a more significant impact of the DP noise on the convergence of PL when $\mu\geq 2$.
The reason is that, when $\mu > 2$, $\varepsilon_{\mathrm{L}}=1+\eta_{\mathrm{L}}-\eta_{\mathrm{L}}\left[\mu+(1-\frac{\mu}{2})\lambda\right]$ increases with $\lambda$ (see \textbf{Lemma~{\ref{Lemma1}}}); when $\mu=2$, $\varepsilon_{\mathrm{L}}$ is independent of $\lambda$, but the impact of DP still grows with $\lambda$ due to the coefficient $\lambda^2$ in (\ref{PerConvergence}). 
{ Note that \textbf{Theorem 1} holds under DP noises with other distributions, since the DP noise has no impact on \textbf{Lemma~\ref{Lemma1}} while the RHS of \eqref{gloOneStep} in \textbf{Lemma~\ref{lemma2}} depends only on the mean and variance $\sigma_z^2$ of the DP noise.}

On the other hand, the impact of DP on the convergence of PL may not always intensify with $\lambda$ when $\mu <2$, because the sign of the first derivative of $\lambda^2 \left(\frac{\varepsilon_{\mathrm{L}}^{t}-\varepsilon_{\mathrm{G}}^{t}}{\frac{\varepsilon_{\mathrm{L}}}{\varepsilon_{\mathrm{G}}}-1}-\frac{\varepsilon_{\mathrm{L}}^{t}-1}{\varepsilon_{\mathrm{L}}-1}\right)$  { in \eqref{PerConvergence2} and $\lambda^2 \left( t \varepsilon_{\mathrm{L}}^t-\frac{\varepsilon_{\mathrm{L}}^{t}-1}{\varepsilon_{\mathrm{L}}-1}\right)$} in \eqref{PerConvergence2_LG} with respect to $\lambda$ 
depends on $\eta_{\mathrm{L}}$, $\varepsilon_{\mathrm{G}}$, and $t$ when $\mu <2$. 



\subsection{Optimization for Convergence}


 Let $h(T,\lambda)$ denote the convergence upper bound of PL after the $T$ aggregation rounds of FL, given the privacy budget. 
 \subsubsection{When $\varepsilon_{\mathrm{L}} \neq \varepsilon_{\mathrm{G}}$} $h(T,\lambda)$ is given by the right-hand side (RHS) of (\ref{theoConverT}).
After reorganization, we have
{\small
\begin{subequations} 
          \label{2Devi}
	\begin{align}
        \label{2Devi1}
        \begin{split}
h(T,&\lambda)\!=\!\Big(\Psi_{2}\!\!+\!\!\frac{\beta\Psi_{1}}{\varepsilon_{\mathrm{L}}\!\!-\!\!\varepsilon_{\mathrm{G}}}\!\!-\!\!\eta_{\mathrm{L}}^{2}\!\left(1\!\!+\!\!\lambda^{2}\right)\!\frac{G}{1\!\!-\!\!\varepsilon_{\mathrm{L}}}\!\!-\!\!\frac{\beta\varphi_{\mathrm{L}}}{(1\!\!-\!\!\varepsilon_{\mathrm{L}})\!(\varepsilon_{\mathrm{L}}\!\!-\!\!\varepsilon_{\mathrm{G}})}T\!\Big)\varepsilon_{\mathrm{L}}^{T}\!\!+\!\!\\&\Big(-\frac{\beta\Psi_{1}}{\varepsilon_{\mathrm{L}}-\varepsilon_{\mathrm{G}}}+\frac{\beta\varphi_{\mathrm{L}}}{(1-\varepsilon_{\mathrm{G}})(\varepsilon_{\mathrm{L}}-\varepsilon_{\mathrm{G}})}T\Big)\varepsilon_{\mathrm{G}}^{T}+\\&\frac{\beta\varphi_{\mathrm{L}}}{(1-\varepsilon_{\mathrm{G}})(1-\varepsilon_{\mathrm{L}})}T+\eta_{\mathrm{L}}^{2}\left(1+\lambda^{2}\right)\frac{G}{1-\varepsilon_{\mathrm{L}}}
\end{split}
\\
=&(H_{1}\!+\!H_{2}T)\varepsilon_{\mathrm{L}}^{T}\!+\!(H_{3}\!+\!H_{4}T)\varepsilon_{\mathrm{G}}^{T}\!+\!H_{5}T\!+\!H_{6} \label{2Devi2} 
        \,,
	\end{align}
	\end{subequations}
where  $\beta=\frac{4\eta_{\mathrm{L}}^{2}\lambda^{2} +2\eta_{\mathrm{L}}\lambda^{2}}{\mu}$, $H_{1}=\Psi_{2}+\frac{\beta\Psi_{1}}{\varepsilon_{\mathrm{L}}-\varepsilon_{\mathrm{G}}}-\eta_{\mathrm{L}}^{2}\!\left(1\!\!+\!\!\lambda^{2}\right)\frac{G}{1-\varepsilon_{\mathrm{L}}}$, $H_{2}=-\frac{\beta\varphi_{\mathrm{L}}}{(1-\varepsilon_{\mathrm{L}})(\varepsilon_{\mathrm{L}}-\varepsilon_{\mathrm{G}})}$, $H_{3}=-\frac{\beta\Psi_{1}}{\varepsilon_{\mathrm{L}}-\varepsilon_{\mathrm{G}}}$, $H_{4}=\frac{\beta\varphi_{\mathrm{L}}}{(1-\varepsilon_{\mathrm{G}})(\varepsilon_{\mathrm{L}}-\varepsilon_{\mathrm{G}})}$, $H_{5}=\frac{\beta\varphi_{\mathrm{L}}}{(1-\varepsilon_{\mathrm{G}})(1-\varepsilon_{\mathrm{L}})}>0$, and $H_{6}=\eta_{\mathrm{L}}^{2}\!\left(1\!\!+\!\!\lambda^{2}\right)\frac{G}{1-\varepsilon_{\mathrm{L}}}>0$. 
}


Let $H_{0}$ denote the lower bound of $(H_{1}+H_{2}T)\varepsilon_{\mathrm{L}}^{T}+(H_{3}+H_{4}T)\varepsilon_{\mathrm{G}}^{T}+H_{6}$ in (\ref{2Devi2}).
Then, $h(T,\lambda)$ has a linear lower bound, denoted by $h_{\rm Low}(T)$; that is
\begin{equation}
\begin{aligned}
    h(T,\lambda)&\geq h_{\rm Low}(T)=H_{0}+H_5T, 
    \\
    \text{with} \,(H_{1}+H_{2}T)&\varepsilon_{\mathrm{L}}^{T}+(H_{3}+H_{4}T)\varepsilon_{\mathrm{G}}^{T}+H_{6}\geq H_0,
    \end{aligned}
\end{equation}

\begin{enumerate}
\item When $\varepsilon_{\mathrm{L}}>\varepsilon_{\mathrm{G}}$, $H_2<0$. 
% $H_3<0$, and $H_4>0$. 
Then, $H_2T\varepsilon_{\mathrm{L}}^T$ first decreases and then increases in $T$. There exists $\underset{T}{\min}(H_2T\varepsilon_{\mathrm{Low}}^T)$.  
% we have $H_{2}T\varepsilon_{\mathrm{L}}^{T}\in[h_{2}^{\mathrm{L}},0]$. 
Also, $H_3<0$. $H_3\varepsilon_{\mathrm{G}}^T \geq H_3$ since $H_3\varepsilon_{\mathrm{G}}^T$ is an increasing function of~$T$.  
$H_4>0$; thus, $H_4T\varepsilon_{\mathrm{G}}^T\geq 0$. 
% We have $H_4T\varepsilon_{\mathrm{G}}^T \in [0,h_4^{\mathrm{U}}]$.
%$H_{3}\varepsilon_{\mathrm{G}}^{T}\in\left[H_{3},0\right)$, and $H_{4}T\varepsilon_{\mathrm{G}}^{T}\in[0,h_4^{\mathrm{U}}]$. 
Considering two possible cases concerning $H_1$, $H_{0}$ is given by 
\begin{enumerate}
    \item If  {$H_1\geq 0$}, then $H_{0}=\underset{T}{\min}(H_2T\varepsilon_{\mathrm{Low}}^T)+H_{3}+H_6$;
    \item If $H_1<0$, then $H_{0}=H_1+\underset{T}{\min}(H_2T\varepsilon_{\mathrm{Low}}^T)+H_{3}+H_6$.
\end{enumerate}
\item When $\varepsilon_{\mathrm{L}}<\varepsilon_{\mathrm{G}}$, $H_2>0$. Hence, $H_2T\varepsilon_{\mathrm{L}}^T \geq 0$. Also, $H_3>0$ and hence $H_3\varepsilon_{\mathrm{G}}^T>0$. Moreover, $H_4<0$ and thus $H_4T\varepsilon_{\mathrm{G}}^T$ first decreases and then increases with respect to $T$, with the existence of $\underset{T}{\min}(H_4T\varepsilon_{\mathrm{Low}}^T)$ confirmed. 
Considering two possible cases concerning $H_1$, $H_{0}$ can be given by
\begin{enumerate}
    \item If  {$H_1\geq 0$}, then $H_{0}=\underset{T}{\min}(H_4T\varepsilon_{\mathrm{Low}}^T)+H_6$;
    \item If $H_1<0$, then $H_{0}=H_1+\underset{T}{\min}(H_4T\varepsilon_{\mathrm{Low}}^T)+H_6$.
\end{enumerate}
\end{enumerate}
As illustrated in Fig.~\ref{fig:lower_bound_1}, given $\lambda$, the optimal $T$, denoted by $T^*$, which minimizes $h(T,\lambda)$, is within $(0,T')$, where $T'$ satisfies $h_{\rm Low}(T')=h(0,\lambda)$, i.e., $T'=\frac{H_{1}+H_{3}+H_6-H_{0}}{H_{5}}$. This is because $h(T,\lambda)>h_{\rm Low}(T')=h(0,\lambda)\geq h(T^*,\lambda),\,\forall T>T'$. As a result, $T^*$ can be obtained effectively using a one-dimensional search with a step size of 1 within~$(0,T')$.  

 \subsubsection{When $\varepsilon_{\mathrm{L}} = \varepsilon_{\mathrm{G}}$} $h(T,\lambda)$ is given by the RHS of (\ref{theoConverT_LG}):
\begin{subequations} 
          \label{2Devi_LG}
	\begin{align}
        \label{2Devi1_LG}
        \begin{split}
h(T,&\lambda)=\Big(-\frac{\left(1+\lambda^{2}\right)\eta_{\mathrm{L}}^{2}G}{1-\varepsilon_{\mathrm{L}}}+\Psi_{2}+\frac{(4\eta_{\mathrm{L}}^{2}+2\eta_{\mathrm{L}})\lambda^{2}}{\varepsilon_{\mathrm{L}}\mu}\cdot\\
&\frac{\Psi_{1}(1-\varepsilon_{\mathrm{L}})^{2}-\varepsilon_{\mathrm{L}}\varphi_{\mathrm{L}}}{(1-\varepsilon_{\mathrm{L}})^{2}}T-\frac{(4\eta_{\mathrm{L}}^{2}+2\eta_{\mathrm{L}})\lambda^{2}\varphi_{\mathrm{L}}}{\varepsilon_{\mathrm{L}}\mu(1-\varepsilon_{\mathrm{L}})}T^{2}\Big)\varepsilon_{\mathrm{L}}^{T}\\
&-\frac{\left(1+\lambda^{2}\right)\eta_{\mathrm{L}}^{2}G}{1-\varepsilon_{\mathrm{L}}}-\frac{(4\eta_{\mathrm{L}}^{2}+2\eta_{\mathrm{L}})\lambda^{2}}{\mu(1-\varepsilon_{\mathrm{L}})}
\end{split}
\\
&=\left(\mathcal{H}_1+\mathcal{H}_2T+\mathcal{H}_3T^{2}\right)\varepsilon_{\mathrm{L}}^{T}+\mathcal{H}_4
\label{2Devi2_LG} 
        \,,
	\end{align}
	\end{subequations}
 where, for the brevity of notation, $\mathcal{H}_{1}=-\frac{\left(1+\lambda^{2}\right)\eta_{\mathrm{L}}^{2}G}{1-\varepsilon_{\mathrm{L}}}+\Psi_{2}$, $\mathcal{H}_2=\frac{(4\eta_{\mathrm{L}}^{2}+2\eta_{\mathrm{L}})\lambda^{2}}{\varepsilon_{\mathrm{L}}\mu}(\Psi_{1}-\frac{\varepsilon_{\mathrm{L}}\varphi_{\mathrm{L}}}{(1-\varepsilon_{\mathrm{L}})^{2}})$, $\mathcal{H}_{3}=-\frac{(4\eta_{\mathrm{L}}^{2}+2\eta_{\mathrm{L}})\lambda^{2}\varphi_{\mathrm{L}}}{\varepsilon_{\mathrm{L}}\mu(1-\varepsilon_{\mathrm{L}})}<0$, and $\mathcal{H}_{4}=-\frac{\left(1+\lambda^{2}\right)\eta_{\mathrm{L}}^{2}G}{1-\varepsilon_{\mathrm{L}}}-\frac{(4\eta_{\mathrm{L}}^{2}+2\eta_{\mathrm{L}})\lambda^{2}}{\mu(1-\varepsilon_{\mathrm{L}})}<0$.


Let 
$\mathcal{H}_0$ 
denote the lower bound of $\left(\mathcal{H}_1+\mathcal{H}_2T\right)\varepsilon_{\mathrm{L}}^{T}+\mathcal{H}_4$ in (\ref{2Devi2_LG}). Then, the lower bound of $h(T,\lambda)$ is given by
\begin{equation}
    h(T,\lambda)\geq h_{\rm Low}(T)=\mathcal{H}_0+\mathcal{H}_3T^{2}\varepsilon_{\mathrm{L}}^{T},
\end{equation}
Since $\mathcal{H}_3<0$, $\mathcal{H}_3T^{2}\varepsilon_{\mathrm{L}}^{T}$ first decreases and then increases.

\begin{enumerate}
\item When $\mathcal{H}_2<0$, $\mathcal{H}_2T\varepsilon_{\mathrm{L}}^T$ first decreases and then increases with respect to $T$. Then, $\underset{T}{\min}(\mathcal{H}_2T\varepsilon_{\mathrm{Low}}^T)$ exists. Considering two possible cases concerning $\mathcal{H}_1$, $\mathcal{H}_0$ is given by
\begin{enumerate}
\item If $\mathcal{H}_1 \geq 0$, then $\mathcal{H}_0=\underset{T}{\min}(\mathcal{H}_2T\varepsilon_{\mathrm{Low}}^T)+\mathcal{H}_4$;
\item If $\mathcal{H}_1 < 0$, then $\mathcal{H}_0=\mathcal{H}_1+\underset{T}{\min}(\mathcal{H}_2T\varepsilon_{\mathrm{Low}}^T)+\mathcal{H}_4$.
\end{enumerate}
\item When $\mathcal{H}_2 \geq 0$, $\mathcal{H}_2T\varepsilon_{\mathrm{L}}^T \geq 0$. Considering the two possible cases concerning $\mathcal{H}_1$, $\mathcal{H}_0$ is given by
\begin{enumerate}
\item If $\mathcal{H}_1 \geq 0$, then $\mathcal{H}_0=\mathcal{H}_4$;
\item If $\mathcal{H}_1 < 0$, then $\mathcal{H}_0=\mathcal{H}_1+\mathcal{H}_4$.
\end{enumerate}
\end{enumerate}
Similarly, the optimal $T^*$ under a given $\lambda$ can be obtained using a one-dimensional search with a step size of 1 within $(0,T'')$, where $T''$ satisfies $h_{\rm Low}(T'')=h(0,\lambda)$.

In both cases, clearly, the convergence of PL depends heavily on that of FL and, in turn, the DP in PFL.



