\begin{definition}[Fairness \cite{li2021ditto}]
\label{DefFairness}
For a group of personalized models $\{\mathbf{\boldsymbol{\varpi}}_{n}\}_{n\in\mathbb{N}}$, the performance distribution fairness is measured by 
\begin{equation}
    \label{DefEquaFair}    \varrho(\boldsymbol{\varpi}_{n})=\mathrm{var_{\mathit{N}}}\left[F_{n}\left(\boldsymbol{\varpi}_{n}\left(\lambda\right)\right)\right] \,,
\end{equation} 
where %$F_n({\boldsymbol{\varpi}}_{n})$ is the loss of the personalized model at client $n$, and 
$\mathrm{var_{\mathit{N}}}\left[F_{n}\left(\boldsymbol{\varpi}_{n}\left(\lambda\right)\right)\right]$ is the variance across the local training losses of the personalized models of all clients. A set of models $\{\mathbf{\boldsymbol{\varpi}}'_{n}\}_{n\in\mathbb{N}}$ is fairer than another set $\{\mathbf{\boldsymbol{\varpi}}_{n}\}_{n\in\mathbb{N}}$ if {$\varrho'=\mathrm{var_{\mathit{N}}}\{F_n({\boldsymbol{\varpi}}'_{n})\}_{n\in\mathbb{N}}<\varrho$. }
% In the proposed PFL, 
The optimal $\lambda$, denoted by $\lambda^{\ast}$, is defined as
\begin{equation}
    \label{DefOptimalLambda}
    \lambda^{\ast}=\underset{\lambda}{\arg\min}\,\mathbb{E}\left\{ \varrho(\boldsymbol{\varpi}_{n}^{\ast}(\lambda))\right\} ,
\end{equation}
where, given~$\lambda$, $\boldsymbol{\varpi}_{n}^{\ast}\left(\lambda\right)$ is client $n$'s optimal PL model.
\end{definition}}

\subsection{Personalized Bayesian Linear Regression With DP}
It is generally different to analyze the performance fairness of PFL, since the performance, e.g., loss, of PFL is typically analytically unavailable and can only be empirically obtained a-posteriori after PFL training.
With reference to Ditto~\cite{li2021ditto},
%With reference to~\cite{li2021ditto}, 
we consider that each client trains a personalized Bayesian linear regression model to shed useful light on the fairness of general ML models.
% when analyzing the fairness of PL. 
Bayesian linear regression models treat regression coefficients and the disturbance variance as random variables 
% rather than fixed but unknown quantities
\cite{seber2003linear}. We set the optimal FL global model $\boldsymbol{\omega}^{\ast}$ as the non-information prior on $\mathbb{R}^{d}$, i.e., uniformly distributed on $\mathbb{R}^{d}$. 

Suppose the optimal FL local model $\boldsymbol{u_n}^{\ast}$ of client $n$ is distributed around the optimal FL global model $\boldsymbol{\omega}^{\ast}$:
\begin{equation}
    \label{u_n}
    \boldsymbol{u}_{n}^{\ast}=\boldsymbol{\omega}^{\ast}+\boldsymbol{\tau}_{n}  \,,
\end{equation}
where $\boldsymbol{\tau}_{n}\sim \mathcal{N}(0,\zeta^{2}\mathbf{I}_{d})$, $\forall n$ are i.i.d. random variables, and $\mathbf{I}_{d}$ is the $d\times d$ identity matrix. 
The local data of client $n$ satisfies 
\begin{equation}
    \label{localmodel}
    \mathbf{Y}_{n}=\mathbf{X}_{n}\boldsymbol{u}_{n}^{\ast}+\boldsymbol{\nu}_{n}  \,.
\end{equation}
Here, $\mathbf{X}_{n}\in\mathbb{R}^{b\times d}$ and $\mathbf{Y}_{n} \in \mathbb{R}^{b}$ denote $b$ samples of client $n$, and $\boldsymbol{\nu}_{n}\in\mathbb{R}^{b}$ under the assumption of {$\boldsymbol{\nu}_{n}\sim \mathcal{N}(0,\sigma^{2}\mathbf{I}_{b})$. }%$\boldsymbol{u}_{n}^{\ast}$ follows the non-informative uniform prior on $\mathbb{R}^{d}$. 

Given the samples $(\mathbf{X}_{n}$, $\mathbf{Y}_{n})$, the loss function of the Bayesian linear regression problem at client $n$ is written as
\begin{equation}
    \label{loss}
    F_{n}\left(\boldsymbol{u}_{n}\right)=\frac{1}{b}\parallel \mathbf{X}_{n}\boldsymbol{u}_{n}-\mathbf{Y}_{n}\parallel^{2}.
\end{equation}
By minimizing (\ref{loss}), the estimate of $\boldsymbol{u}_{n}^{\ast}$ is~\cite[Eq.~(12)]{li2021ditto}
\begin{equation}
    \label{estimatedmodel}    \hat{\boldsymbol{u}}_{n}=\left(\mathbf{X}_{n}^{\intercal}\mathbf{X}_{n}\right)^{-1}\mathbf{X}_{n}^{\intercal}\mathbf{Y}_{n}  .
\end{equation}
By plugging (\ref{loss}) into (\ref{fn_1}), the optimal global model is
\begin{subequations}
    \label{g_loss}
\begin{align}
\boldsymbol{\omega}^{\ast}&=\underset{\boldsymbol{\omega}}{\arg\min}\, \frac{1}{Nb} \sum_{n=1}^{N} \parallel \mathbf{X}_{n}\boldsymbol{\omega}-\mathbf{Y}_{n}\parallel^{2} \\
&=\sum_{n=1}^{N}\left(\mathbf{X}^{\intercal}\mathbf{X}\right)^{-1}\mathbf{X}_{n}^{\intercal}\mathbf{X}_{n}\hat{\boldsymbol{u}}_n ,    
\end{align}
\end{subequations}
where $\mathbf{X}\in\mathbb{R}^{Nb\times d}$ collects $Nb$ samples of all clients, i.e., $\mathbf{X}=(\mathbf{X}_{1}^{\top}\: \mathbf{X}_{2}^{\top}\: \cdots \: \mathbf{X}_{N}^{\top} )^{\top}$.

With DP, the server receives the perturbed version of 
% $u_n^{\ast}$, 
the estimated local model, denoted by $\overset{\sim}{\boldsymbol{u}}_{n}$, as given by 
\begin{equation}
%\begin{align}
    \label{noisyestimation1}
    \overset{\sim}{\boldsymbol{u}}_{n}=\hat{\boldsymbol{u}}_n+\mathbf{z}_{n}  = \left(\mathbf{X}_{n}^{\intercal}\mathbf{X}_{n}\right)^{-1}\mathbf{X}_{n}^{\intercal}\mathbf{Y}_{n}+\mathbf{z}_{n} \,.
        %\label{noisyestimation2}
%\end{align}
\end{equation} 
By replacing $\hat{\boldsymbol{u}}_n$ with $\overset{\sim}{\boldsymbol{u}}_n$, the DP perturbed version of the optimal global model, denoted by $\overset{\sim}{\boldsymbol{\omega}}^{\ast}$, is given by
	\begin{equation} 
     \overset{\sim}{\boldsymbol{\omega}}^{\ast}=\sum_{n=1}^{N} \left(\mathbf{X}^{\intercal}\mathbf{X}\right)^{-1}\mathbf{X}_{n}^{\intercal}\mathbf{X}_{n}\overset{\sim}{\boldsymbol{u}}_n,
     \label{omega*2}
	\end{equation} 





\begin{lemma}
\label{noisy_pL}
%Assume that 
With $\mathbf{X}_{n}^{\intercal}\mathbf{X}_{n}=\rho\mathbf{I}_{d}$, $\forall n \in \mathbb{N}$ under independently sampled or generated data samples \cite{li2021ditto}, 
the optimal PL model with DP, $\overset{\sim}{\boldsymbol{\varpi}_{n}^{\ast}}\left(\lambda\right)$, and the optimal FL local model, $\boldsymbol{u}_n^{\ast}$ in (\ref{u_n}), can be written as
	\begin{equation} 
	\begin{split}
        \label{Optimal_w_n}
     \overset{\sim}{\boldsymbol{\varpi}}_{n}^{\ast}\left(\lambda\right)=&\frac{b}{\left(2-\lambda\right)\rho+b\lambda}\left(\left(\frac{\left({2-\lambda}\right)\rho}{b}+\frac{\lambda}{N}\right)\hat{\boldsymbol{u}}_{n} \right.\\
     &\left.+\frac{\lambda}{N}\underset{m\in \mathbb{N},m\neq n}{\sum}\hat{\boldsymbol{u}}_{m}+\frac{\lambda}{N} \sum_{n=1}^{N} {\mathbf{z}_{n}}\right) ;
	\end{split}
	\end{equation} 
	\begin{equation} 
	%\begin{split}
        \label{Optimal_u_n}
     \boldsymbol{u}_{n}^{\ast}=\frac{\sigma_{w}^{2}\rho}{\sigma^{2}}\hat{\boldsymbol{u}}_{n}+ 
     \frac{\sigma_{w}^{2}\rho}{\sigma^{2}+N\zeta^{2}\rho}\underset{m\in\mathbb{N},m\neq n}{\sum}\hat{\boldsymbol{u}}_{m}+\boldsymbol{\vartheta}_{n} , 
	%\end{split}
	\end{equation}
where $\boldsymbol{\vartheta}_{n}\sim \mathcal{N}(0,\sigma_{w}^{2} \mathbf{I}_{d})$ and $\sigma_{w}^{2}=\left(\frac{N-1}{\frac{\sigma^{2}}{\rho}+N\zeta^{2}}+\frac{\rho}{\sigma^{2}}\right)^{-1}$.
\end{lemma}

\begin{proof}
    See \textbf{Appendix \ref{BLR_models}}.
\end{proof}







We note that in Ditto, the optimal personalized models ${\boldsymbol{\varpi}_{n}^{\ast}}\left(\lambda\right)$, $\forall n \in \mathbb{N}$ are deterministic, provided the estimated local models $\hat{\boldsymbol{u}}_{n}$ ($\forall n \in \mathbb{N}$) and $\lambda$.
{
By contrast, in DP-Ditto, the PL models $\overset{\sim}{\boldsymbol{\varpi}}_{n}^{\ast}\left(\lambda\right)$, $\forall n \in \mathbb{N}$ are not deterministic. This is because the DP noise, $\mathbf{z}_{n}$, is added on the estimated local models $\hat{\boldsymbol{u}}_n$ for the FL global model updating and, consequently, it is coupled with $\lambda$ in $\overset{\sim}{\boldsymbol{\varpi}}_{n}^{\ast}\left(\lambda\right)$; see (\ref{Optimal_w_n}). Considering the difference between the optimal FL local model $\boldsymbol{u}_{n}^{\ast}$ in (\ref{Optimal_u_n}) and its estimate $\hat{\boldsymbol{u}}_{n}$ is random and captured by $\boldsymbol{\vartheta}_{n}$, we have to analyze the joint distribution of the two random variables $\mathbf{z}_{n}$ in (\ref{Optimal_w_n}) and $\boldsymbol{\vartheta}_{n}$ {in (\ref{Optimal_u_n})}, $\forall n \in \mathbb{N}$, and obtain the fairness expression with respect to $\lambda$.
}


Given the optimal FL local model without DP, $\boldsymbol{u}_n^{\ast}$, and the optimal PL model with DP, $\overset{\sim}{\boldsymbol{\varpi}}_n^{\ast}(\lambda)$, the fairness $\varrho(\overset{\sim}{\boldsymbol{\varpi}_{n}^{\ast}}(\lambda))$ of the PL models among all clients is established, as follows.

\begin{theorem}
\label{FAIRNESS}
Given $\lambda$ and the variance $\sigma_{z}^{2}$ of the DP noise, the fairness of the personalized Bayesian linear regression model, $R(\lambda)$, can be measured by
\begin{equation} 
	\begin{split}
        \label{fairness_R}
        \!\!\!\!R(\lambda)&\!=   \! 2d\!\left[\sigma_{w}^{2}\!+\!\left[\alpha_{0}\left(\lambda\right)\right]^{2}\frac{\sigma_{z}^{2}}{N^{2}}\right]\!\!+\!4\!\left[\sigma_{w}^{2}\!+\!\left[\alpha_{0}\left(\lambda\right)\right]^{2}\!\frac{\sigma_{z}^{2}}{N^{2}}\right] \!\times\! \\
        &\left(S_{1}\!-\!S_{2}\alpha_{0}\left(\lambda\right)\right)^{2}G_{1}\!+\!\left[S_{1}\!-\!S_{2}\alpha_{0}\left(\lambda\right)\right]^{4}\left(G_{2}\!-\!G_{1}^{2}\right),
	\end{split}
	\end{equation} 
where $\alpha_{0}\left(\lambda\right)=\frac{b\lambda}{\left(2-\lambda\right)\rho+b\lambda}$, $S_{1}=\frac{\sigma^{2}}{N\left(\sigma^{2}+\rho\zeta^{2}\right)}$, $S_{2}=\frac{1}{N}$, $G_{1}= \sum_{l=1}^{d} \frac{1}{N}\sum_{n=1}^{N}\left[\alpha_{nl}^{2}\right]$, and $G_{2}=\frac{1}{N}\sum_{n=1}^{N}\left[\left( \sum_{l=1}^{d} \alpha_{nl}^{2}\right)^{2}\right]$. 
% are defined for the brevity of notation.    
\end{theorem}

\begin{proof}
    See \textbf{Appendix \ref{pFAIRNESS}}.
\end{proof}

