        &\left(S_{1}-S_{2}\alpha_{0}^{\ast}\right)-4S_{2}\left(G_{2}-G_{1}^{2}\right)\left(S_{1}-S_{2}\alpha_{0}^{\ast}\right)^{3}=0,\label{opAlpha0}
	\end{align}
	% \end{equation} 
where $\alpha_{0}^{\ast}=\frac{b\lambda^{\ast}}{\left(2-\lambda^{\ast}\right)\rho+b\lambda^{\ast}}$.
