\begin{document}

\begin{abstract}
A proper $k$-colouring of a graph $G$ is called $h$-conflict-free if every vertex $v$ has at least $\min\, \{h, \deg(v)\}$ colours appearing exactly once in its neighbourhood. Let $\pcf^h(G)$ denote the minimum $k$ such that such a colouring exists. We show that for every fixed $h\ge 1$, every graph $G$ of maximum degree $\Delta$ satisfies $\chi_{\rm{pcf}}^h(G) \le h\Delta + \mathcal{O}(\log \Delta)$. This expands on the work of Cho \emph{et al.}, and improves a recent result of Liu and Reed in the case $h=1$. We conjecture that for every $h\ge 1$ and every graph $G$ of maximum degree $\Delta$ sufficiently large, the bound $\pcf^h(G) \le h\Delta + 1$ should hold, which would be tight.
When the minimum degree $\delta$ of $G$ is sufficiently large, namely $\delta \ge \max\{100h, 3000\log \Delta\}$, we show that this upper bound can be further reduced to $\chi_{\rm{pcf}}^h(G) \le \Delta + \bigo{\sqrt{h\Delta}}$. This improves a recent bound from Kamyczura and Przybyło when $\delta \le \sqrt{h\Delta}$. 
\end{abstract}


\maketitle



\section{Introduction}

For a positive integer $k$, let us denote $[k] \coloneqq \{1,\dots,k\}$ the set of the first $k$ integers. A \emph{$k$-colouring} of a graph $G$ is an assignment $\sigma\colon V(G) \rightarrow [k] $. A colouring $\sigma$ of $G$ is \emph{proper} if $\sigma(u) \neq \sigma(v)$ for every edge $uv \in E(G)$. Given a colouring $\sigma$ and a vertex $v \in V(G)$, a \emph{witness} of $v$ is a neighbour $u \in N(v)$ such that the colour $\sigma(u)$ appears exactly once in $N(v)$; we say that $\sigma(u)$ is a \emph{solitary colour} of $v$ in $\sigma$.
The colouring $\sigma$ is \emph{proper conflict-free} (or simply \emph{pcf}) if it is proper and every non-isolated vertex $v$ has a witness. We let $\pcf(G)$ be the smallest integer $k$ such that a pcf $k$-colouring of $G$ exists. 
% The smallest integer $k$ such that a pcf $k$-colouring of $G$ exists is denoted $\pcf(G)$. 
The notion of pcf colouring was introduced by Fabrici \emph{et al.} \cite{fabrici2023proper}, and was first investigated in the class of graphs of maximum degree $\Delta$ by Caro, Petru\v{s}evski and \v{S}krekovski \cite{caro2023remarks}. Among other results, they obtained the upper bound $\pcf(G) \le 5\Delta(G)/2$, and conjectured that the optimal upper bound should actually be $\Delta(G)+1$.

\begin{conj}[Caro, Petru\v{s}evski, \v{S}krekovski {\cite[Conjecture 6.4]{caro2023remarks}}]\label{conj:pcf}
    If $G$ is a connected graph of maximum degree $\Delta\ge 3$, then $\pcf(G)\le \Delta+1$.
\end{conj}

The condition $\Delta \ge 3$ is needed because the conjectured bound does not hold for cycles. Indeed $\pcf(C_5)=5 = \Delta(C_5)+3$, and for every other cycle $C$ whose length is not a multiple of $3$, $\pcf(C) = 4 = \Delta(C)+2$. The condition that $G$ is connected ensures that there is no isolated vertex.
The conjectured upper bound is best possible. For instance, if $G$ is a graph obtained by subdividing once any subset of edges from the complete graph $K_n$ with $n\ge 5$, then $\pcf(G)=n=\Delta(G)+1$. In particular, when $G={K_n}^{1/2}$, the difference between $\chi(G)$ and $\pcf(G)$ is unbounded; we have $\chi(G)=2$ while $\pcf(G)=n$.

As a first step towards resolving \cref{conj:pcf}, Cranston and Liu \cite{CrLi24} observed that a simple greedy algorithm provides a pcf $(2\Delta+1)$-colouring of any graph $G$ of maximum degree $\Delta$. They moreoever proved that $\pcf(G) < 1.656\Delta$ when $\Delta$ is large enough. More recently, Liu and Reed \cite{liu2024asymptotically} proved that \cref{conj:pcf} holds asymptotically, by showing $\pcf(G) \le \Delta + \mathcal{O}(\Delta^{2/3}\log \Delta)$ as $\Delta \to \infty$. Our first contribution is to improve this upper bound by eliminating the polynomial factor in the second-order term.

\begin{thm}\label{thm:pcf-log}
    Let $G$ a graph of maximum degree $\Delta$, then $$\pcf(G) \le \Delta + \bigO{\log \Delta}.$$
\end{thm}

Proper conflict-free colourings can be seen as a relaxation of distance-$2$ colourings: the latter require all neighbours of a vertex to have different colours, whereas the former only ask for one neighbour to have a colour distinct from the others. To interpolate between those two notions, one can introduce the notion of \emph{proper $h$-conflict-free $k$-colourings} (or \emph{$h$-pcf $k$-colouring} for short), for some integers $h,k\ge 1$. Those are proper $k$-colourings where every vertex $v$ has at least $\min\, \{h, \deg(v)\}$ solitary colours. In particular, for a graph $G$ of maximum degree $\Delta$, a $1$-pcf $k$-colouring of $G$ is simply a pcf $k$-colouring of $G$, while an $h$-pcf $k$-colouring is a distance-$2$ $k$-colouring of $G$ whenever $h \ge \Delta-1$. 
For every $h\ge 1$, we denote $\pcf^h(G)$ the minimum $k$ such that an $h$-pcf $k$-colouring of $G$ exists. A simple greedy algorithm, inspired by the observation of Cranston and Liu \cite{CrLi24}, yields the following upper bound. We include the proof with a complete description of the greedy algorithm, which will be useful in an alternative form in the rest of the paper.

\begin{prop}\label{prop:h-pcf-greedy}
    Let $G$ be a graph of maximum degree $\Delta$, and $h \ge 1$ an integer. Then $$\pcf^h(G) \le (h+1)\Delta + 1.$$
\end{prop}
\begin{proof}
    Fix any linear ordering $(v_1, \dots, v_n)$ of $V(G)$. For a vertex $v \in V(G)$, let $\W(v)$ be the first $\min\,\{h, \deg(v)\}$ neighbours of $v$ in the ordering. For $i$ from $1$ to $n$, colour $v_i$ with the first colour which does not appear in $N(v_i)$, nor in $\W(u)$ for $u \in N(v_i)$. Let $\sigma$ be the colouring obtained at the end of this procedure. One easily checks that $\sigma$ is proper. Furthermore, for all $v \in V$, the vertices of $\W(v)$ are witnesses of $v$ (the fact that $\W(v)$ is coloured before $N(v)\setminus \W(v)$ is important), therefore $\sigma$ is $h$-pcf. Observe that the number of colour constraints when colouring $v_i$ is at most $(h+1)\deg(v)$, therefore $\sigma$ uses at most $(h+1)\Delta + 1$ colours.
\end{proof}

\begin{rk}
    With the additional assumption that $G$ is $d$-degenerate, we obtain $\pcf^h(G) \le h\Delta + d + 1$.
\end{rk}

Cho \emph{et al.} \cite{cho2025brooks} improved this upper bound by reducing the number of colours needed by $2$.

\begin{thm}[Cho, Choi, Kwon, Park, 2025]\label{thm:pcf-cho}
    Let $G$ be a graph of maximum degree $\Delta$, and let $1 \le h \le \Delta - 2$ be an integer. Then $\pcf^h(G) \le (h+1)\Delta - 1$.
\end{thm}

For the specific case $h = \Delta - 2$, they exhibit a graph $G$ of maximum degree $\Delta$ arbitrarily large such that $\pcf^{h}(G) = (h+1)(\Delta - 1)$. Note that this last term is also equal to $h\Delta + 1$. We consider the opposite end of the spectrum by considering $h$ a fixed constant, and make an asymptotic improvement on \cref{thm:pcf-cho} in that case.

\begin{thm}\label{thm:pcf-upper}
    Let $h\ge 1$ be a fixed integer. If $G$ is a connected graph of maximum degree $\Delta$, then $$\pcf^h(G)\le h\Delta + \bigO{\log\Delta}.$$
\end{thm}

\cref{thm:pcf-log} is a direct corollary of \cref{thm:pcf-upper} with $h=1$. We note that the hidden constant in the term $\bigo{\log\Delta}$ has a linear dependency in $h$; this constant is explicitly stated in \cref{cor:h-pcf}.\\


The notion of pcf colourings can also be seen as a strengthening of \emph{odd colourings}, cf. \cite{petruvsevski2022colorings,CCKP22+,dai2023new}.
For a graph $G$ and an integer $h \ge 1$, an \emph{$h$-odd colouring} of $G$ is a proper colouring such that every vertex $v$ observes at least $\min\, \{h, \deg(v)\}$ colours in its neighbourhood that appear an odd number of times. Let $\odd^h(G)$ be the minimum number of colours required for an $h$-odd colouring of $G$, and $\odd(G) \coloneqq \odd^1(G)$. Clearly, $\odd^h(G) \le \pcf^h(G)$ for every $h\ge 1$. A weaker version of \cref{conj:pcf} was first formulated in \cite{CPS22+} for the odd chromatic number of graphs of maximum degree $\Delta$, and it was shown in \cite[Theorem 3]{dai2023new} that $\odd(G) \le \Delta + \bigO{\log\Delta}$. In that sense, \cref{thm:pcf-log} is also a strengthening of this result.

If $h$ is a fixed integer and $G$ is a graph of maximum degree $\Delta$, then we have $\odd^h(G) \le h\Delta + \bigO{\log\Delta}$ as a direct consequence of \cref{thm:pcf-upper}. The first-order term of this upper bound was shown to be tight in \cite[Proposition 28]{dai2023new}.

\begin{prop}[Dai, Ouyang, Pirot, 2024]\label{prop:lower-bound}
    Let $h \ge 1$ be a fixed integer. For infinitely many values of $\Delta$, there exists a graph $G$ of maximum degree $\Delta$ and minimum degree $h+1$ such that 
    \[\odd^h(G) \ge h\Delta + 1.\]
\end{prop}

In turn, \cref{prop:lower-bound} demonstrates that \cref{thm:pcf-upper} is tight up to the second-order term, i.e. for every fixed integer $h \ge 1$, there exists a graph of maximum degree $\Delta$ arbitrarily large such that $\pcf^h(G) \ge h\Delta + 1$. In light of these observations, we propose an extended version of \cref{conj:pcf}.

\begin{conj}
    Let $h \ge 1$ be an integer, and $G$ be a graph of maximum degree $\Delta$ sufficiently large. Then $$\pcf^h(G) \le h\Delta + 1.$$
\end{conj}

The lower bound provided by \cref{prop:lower-bound} relies on a graph construction with many vertices of small degree (namely, of degree $h+1$). When there is an additional restriction on the minimum degree of $G$, it is possible to derive smaller upper bounds on $\pcf^h(G)$. 
In particular, Liu and Reed \cite{LiRe24+} have recently proved that \cref{conj:pcf} holds for regular graphs in a strong sense. Their result can be stated as follows.

\begin{thm}[Liu, Reed, 2024+]
\label{thm:peaceful}
    For every graph $G$ of maximum degree $\Delta$ and minimum degree $\delta > \frac{8000}{8001}\Delta$, letting $h\coloneqq \delta - \frac{8000}{8001}\Delta$, one has
    \[ \pcf^h(G) \le \Delta+1. \]
\end{thm}

The condition on the minimum degree in \cref{thm:peaceful} is of course very restrictive. One could wonder what happens when this condition is relaxed.
This has been considered by Kamyczura and Przybyło \cite{kamyczura2024conflict}, who showed the following.

\begin{thm}[Kamyczura, Przybyło, 2024]\label{thm:kamyczura}
    Let $G$ be a graph of maximum degree $\Delta$ and minimum degree $\delta$. For every integer $h$ satisfying $20 \log \Delta \le h \le \delta/75$, one has
    \[\pcf^h(G) < \Delta + \frac{30 h \Delta}{\delta}.\]
\end{thm}

The condition on $h$ implies that $\delta > 1500\log\Delta$.
Note that the condition $h\ge 20\log \Delta$ in the above statement is non-restrictive, since $\pcf^h(G)$ is monotonous in $h$: when $h< 20\log \Delta$, one can use $\pcf^h(G) \le \pcf^{\ceil{20 \log \Delta}}(G)$ to obtain an upper bound on $\pcf^h(G)$ with an application of \Cref{thm:kamyczura}. 
A direct consequence of \Cref{thm:kamyczura} is that, when $h$ is a fixed integer and $\delta \gg \log\Delta$, one has $\pcf^h(G) \le \Delta + \bigo{\Delta \log\Delta/\delta}$. We improve this bound when the minimum degree is not too large.

\begin{thm}\label{thm:pcf-large-mindeg}
    Let $G$ be a graph of maximum degree $\Delta$ and minimum degree $\delta$. For every integer $h$ satisfying $30 \log \Delta \le h \le \delta/100$, one has
    \[\pcf^h(G) \le \Delta + \bigO{\sqrt{h\Delta}}.\]
\end{thm}

The upper bound provided by \cref{thm:pcf-large-mindeg} is smaller than that of \cref{thm:kamyczura} in the regime $\delta = \bigo{\sqrt{h\Delta}}$, and performs best at $\delta = 100h$. 
However, we suspect that there is still room for improvement in that regime. For matters of comparison, it was proved in \cite[Corollary 6.3]{dai2023new} that if $3\log\Delta \le h \le \delta/2$, then $\odd^h(G) \le \Delta + \bigo{h}$, and we conjecture that a similar bound should hold for $h$-pcf colourings as well.

\begin{conj}
    \label{conj:h-pcf}
    There exist absolute constants $c_1,c_2 > 0$ such that the following holds. Let $G$ be a graph of maximum degree $\Delta$ and minimum degree $\delta$. For every integer $h$ satisfying $c_1 \log \Delta \le h \le c_2 \,\delta$, one has
    \[\pcf^h(G) \le \Delta + \bigO{h}.\]
\end{conj}

In some sense, our contribution in \cref{thm:pcf-large-mindeg} is a halfway progression towards this conjecture, when $h = \Theta(\delta)$.  

