\section{Proof of Theorem \ref{thm:bu}}

We first prove an auxiliary lemma. Suppose that $T$ is a tree-shaped AADT whose root has two children; we call the subtrees spanned by these children $T_1$ and $T_2$. If $\mathcal{D}_i$ is the set of BDS in $T_i$, then $\mathcal{D}_1 \cap \mathcal{D}_2 = \varnothing$ due to the tree-shaped property, and $\mathcal{D}_1 \cup \mathcal{D}_2 = \mathcal{D}$. Hence $\mathbb{B}^{\mathcal{D}} \cong \mathbb{B}^{\mathcal{D}_1} \times \mathbb{B}^{\mathcal{D}_2}$. Thus we can uniquely write each element $\vec{\delta} \in \mathbb{B}^{\mathcal{D}}$ as $(\vec{\delta}_1,\vec{\delta}_2)$, with $\vec{\delta}_i \in \mathbb{B}^{\mathcal{D}_i}$. In this terminology, we have the following lemma:

\begin{lemma}
Let $T$ be a tree-shaped AADT whose root has two children; the ADTs spanned by these children are called $T_1$ and $T_2$, respectively. Let $\mathcal{D}_i$ be the set of BDS in $T_i$. Furthermore, let $\rho_1$, $\rho_2$ be the optimal attack response functions of $T_1$ and $T_2$, respectively. Then for all $\vec{\delta}_i \in \mathbb{B}^{\mathcal{D}_i}$,
\begin{equation*}
\hat{\beta}_A(\rho(\vec{\delta}_1,\vec{\delta}_2)) = \hat{\beta}_A(\rho_1(\vec{\delta}_1)) \circ_A \hat{\beta}_A(\rho_2(\vec{\delta}_2)).
\end{equation*}
\end{lemma}

\begin{proof}
We prove this statement for the case $\gamma(R_T) = \mathtt{OR}$, $\tau(R_T) = \mathtt{A}$; the other cases are similar. We first show $\hat{\beta}_A(\rho(\vec{\delta}_1,\vec{\delta}_2)) \preceq_A \hat{\beta}_A(\rho_1(\vec{\delta}_1)) \oplus_A \hat{\beta}_A(\rho_2(\vec{\delta}_2))$. To see this, note that since $R_T$ is an \texttt{OR}-gate, we have
\begin{align*}
&f_T((\rho_1(\vec{\delta}_1),\vec{0}),(\vec{\delta}_1,\vec{\delta}_2),R_T) \\
&= f_{T_1}(\rho_1(\vec{\delta}_1),\vec{\delta}_1,R_{T_1}) \vee f_{T_2}(\vec{0},\vec{\delta}_2,R_{T_2}) \\
&= 1 \vee f_{T_2}(\vec{0},\vec{\delta}_2,R_{T_2}) \\
&= 1.
\end{align*}
By definition of $\rho(\vec{\delta}_1,\vec{\delta}_2)$, this means that
\begin{align*}
\hat{\beta}_A(\rho(\vec{\delta}_1,\vec{\delta}_2)) &\preceq_A \hat{\beta}_A(\rho_1(\vec{\delta}_1),\vec{0}) \\
&= \hat{\beta}_A(\rho_1(\vec{\delta}_1)).
\end{align*}
Analogously we can show $\hat{\beta}_A(\rho(\vec{\delta}_1,\vec{\delta}_2)) \preceq_A \hat{\beta}_A(\rho_2(\vec{\delta}_2))$; since $\oplus_A$ selects the minimum w.r.t. $\preceq_A$, this implies $\hat{\beta}_A(\rho(\vec{\delta}_1,\vec{\delta}_2)) \preceq_A \hat{\beta}_A(\rho_1(\vec{\delta}_1)) \oplus_A \hat{\beta}_A(\rho_2(\vec{\delta}_2))$.

Next, we show $\hat{\beta}_A(\rho_1(\vec{\delta}_1)) \oplus_A \hat{\beta}_A(\rho_2(\vec{\delta}_2)) \preceq_A \hat{\beta}_A(\rho(\vec{\delta}_1,\vec{\delta}_2))$. Let $\rho(\vec{\delta}_1,\vec{\delta}_2) = (\vec{\alpha}_1,\vec{\alpha}_2)$. Then by definition,
\begin{align*}
1 &= f_T((\vec{\alpha}_1,\vec{\alpha}_2),(\vec{\delta}_1,\vec{\delta}_2),R_T) \\
&= f_{T_1}(\vec{\alpha}_1,\vec{\delta}_1,R_{T_1}) \vee f_{T_2}(\vec{\alpha}_2,\vec{\delta}_2,R_{T_2}).
\end{align*}
Without loss of generality, assume $f_{T_1}(\vec{\alpha}_1,\vec{\delta}_1,R_{T_1})= 1$. Then
\begin{align*}
\hat{\beta}_A(\rho_1(\vec{\delta}_1)) &\preceq_A \hat{\beta}_A(\vec{\alpha}_1) \\
&= \bigotimes_{i: \alpha_{1,i}= 1} \beta(a_i) \\
&\preceq_A \bigotimes_{i: \alpha_{1,i}= 1} \beta(a_i) \otimes\bigotimes_{i: \alpha_{2,i}= 1} \beta(a'_i) \\
&= \hat{\beta}_A(\vec{\alpha}_1,\vec{\alpha}_2) \\
&= \hat{\beta}_A(\rho(\vec{\delta}_1,\vec{\delta}_2).
\end{align*}
Here the $a_i$ are the BAS of $T_1$, while the $a'_i$ are the BAS of $T_2$. This proves $\hat{\beta}_A(\rho_1(\vec{\delta}_1)) \oplus_A \hat{\beta}_A(\rho_2(\vec{\delta}_2)) \preceq_A \hat{\beta}_A(\rho(\vec{\delta}_1,\vec{\delta}_2))$, which together with the previous inequality proves equality.
\end{proof}

We also need a second lemma to show that the semiring operations behave nicely with respect to $\sqsubseteq$.

\begin{lemma} \label{lem:pf}
Let $\circ_A$ be either $\otimes_A$ or $\oplus_A$, and let $\psi$ be the binary operation on $V_D \times V_A$ given by $\psi((x,y),(x',y')) = (x \otimes_D x',y \circ_A y')$. Then for any two subsets $X, X' \subseteq V_D \times V_A$ we have
\[
\underline{\min}_{\sqsubseteq}(\psi(X,X')) = \underline{\min}_{\sqsubseteq}(\psi(\underline{\min}_{\sqsubseteq}(X),X')).
\]
\end{lemma}

\begin{proof}
Either way we have that $y \preceq_A y'$ implies $y''  \circ_A y \preceq_A y'' \circ_A y'$. We now first prove 
\begin{equation} \label{eq:BUpf1}
\underline{\min}_{\sqsubseteq}(\psi(X,X')) \subseteq \underline{\min}_{\sqsubseteq}(\psi(\underline{\min}_{\sqsubseteq}(X),X')).
\end{equation}
Let $(x,y) \in X$ and $(x',y') \in X'$ be such that $\psi((x,y),(x',y'))$ is Pareto optimal in $\psi(X,X')$. We first prove that $\psi((x,y),(x'y')) \in \psi(\underline{\min}_{\sqsubseteq}(X),X')$. Let $(x'',y'') \in X$ be such that $(x'',y'') \sqsubseteq (x,y)$, i.e., $x'' \preceq_D x$ and $y \preceq_A y''$. Then $x'' \otimes_D x' \preceq_D x \otimes_D x'$ and $y \circ_A y' \preceq_A \circ y'' \circ_A y'$; hence
\[
\psi((x'',y''),(x',y')) \sqsubseteq \psi((x,y),(x',y').
\]
Since the RHS is Pareto optimal in $\psi(X,X')$, equality must hold; hence $\psi((x,y),(x'y')) \in \psi(\underline{\min}_{\sqsubseteq}(X),X')$. Furthermore, it cannot be dominated by elements of $\psi(\underline{\min}_{\sqsubseteq}(X),X')$ as it is not dominated by elements of $\psi(X,X')$; hence $\psi((x,y),(x',y')) \in \underline{\min}_{\sqsubseteq}(\psi(\underline{\min}_{\sqsubseteq}(X),X'))$, and equality holds in \eqref{eq:BUpf1}. Next, we prove
\begin{equation} \label{eq:BUpf2}
\underline{\min}_{\sqsubseteq}(\psi(X,X')) \supseteq \underline{\min}_{\sqsubseteq}(\psi(\underline{\min}_{\sqsubseteq}(X),X')).
\end{equation}
Let $(x,y) \in \underline{\min}_{\sqsubseteq}(X)$ and let $(x',y') \in X'$ be such that $\psi((x,y),(x',y'))$ is Pareto optimal in $\psi(\underline{\min}_{\sqsubseteq}(X),X')$. Clearly $\psi((x,y),(x',y')) \in \psi(X,X')$; we need to show that it is Pareto optimal there. Let $(z,w) \in X$, $(z',w') \in X'$ be such that $\psi((z,w),(z',w')) \in \underline{\min}_{\sqsubseteq}(\psi(X,X'))$ and such that
\begin{equation} \label{eq:BUpf3}
\psi((z,w),(z',w')) \sqsubseteq \psi((x,y),(x',y')).
\end{equation}
By \eqref{eq:BUpf1} we have that $\psi((z,w),(z',w'))$ is Pareto optimal in $\psi(\underline{\min}_{\sqsubseteq}(X),X'))$. This also holds for $\psi((x,y),(x',y'))$. Hence equality holds in \eqref{eq:BUpf3}, which in turn implies that \eqref{eq:BUpf2} holds. This completes the proof.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:bu}]
We prove by induction that $\mathtt{BU}(T,v) = \operatorname{PF}(T_v)$ for all nodes $v$ in $T$. The statement is clear if $v$ is a leaf. Now suppose $v$ has two children $v_1$ and $v_2$, for which the induction hypothesis holds. Then
\begin{align*}
\mathtt{BU}(T,v) &= \underline{\min}_{\sqsubseteq}(\psi(\mathtt{BU}(T,v_1),\mathtt{BU}(T,v_2)))\\
&= \underline{\min}_{\sqsubseteq}(\psi(\underline{\min}_{\sqsubseteq}(\hat{\beta}(\mathbb{B}^{\mathcal{D}_1})),\underline{\min}_{\sqsubseteq}(\hat{\beta}(\mathbb{B}^{\mathcal{D}_1}))))\\
&= \underline{\min}_{\sqsubseteq}(\psi(\hat{\beta}(\mathbb{B}^{\mathcal{D}_1}),\hat{\beta}(\mathbb{B}^{\mathcal{D}_1})))\\
&= \underline{\min}_{\sqsubseteq}(\hat{\beta}(\mathbb{B}^{\mathcal{D}})\\
&= \operatorname{PF}(T_v).
\end{align*}
Here we use Lemma \ref{lem:pf} twice in the third $=$.
\end{proof}

\section{Proof of Theorem \ref{thm:bdd}}

We will prove this theorem for $\tau(R_T) = \mathtt{A}$; the case $\tau(R_T) = \mathtt{D}$ is proven analogously. Note that the definition of $\rho$, and with it those of $\hat{\beta}$ and $\operatorname{PF}(T)$, depend on $T$ only via $f_T$. Therefore, we can define $\operatorname{PF}(f)$ for any Boolean function $f$ whose variables are partitioned into $\mathcal{D} \cup \mathcal{A}$. Furthermore, for the algorithm $\mathtt{BDD_{BU}}$ we do not need the full AADT; we just need $D_{\mathcal{D}},D_{\mathcal{D}},\beta_D,\beta_A$ and $\tau(R_T)$. All other information is stored in the structure function $f_T$, which is the same as the function $f$. Consider $D_{\mathcal{D}},D_{\mathcal{D}},\beta_D,\beta_A$ and $\tau(R_T) = \mathtt{A}$ fixed, and write $\mathtt{Z}(B,w)$ for the algorithm that performs $\mathtt{BDD_{BU}}(T,B,w)$ for an appropriate AADT $T$. Then it suffices to prove the following theorem:

\begin{theorem}
Let $f$ be a Boolean function with variables $\mathcal{D} \cup \mathcal{A}$, and let $<$ be a linear order on the variables such that $d < a$ for all $d \in \mathcal{D}$ and $a \in \mathcal{A}$. Let $B$ be the ROBDD with variable ordering $<$ representing $f$. Then $\mathtt{Z}(B,R_B) = \operatorname{PF}(f)$.
\end{theorem}

\begin{proof}
We prove this by induction on the size of $B$. If $B$ has one node, then $f$ is a constant function, for which the theorem holds. If $Lab(R_B) \in \mathcal{A}$, then all variables in $B$ are in $\mathcal{A}$; in this case, the result directly follows from BDD-based analysis of semiring attack tree metrics \cite{Lopuha_Efficient_2023}. Now suppose $Lab(R_B) = d \in \mathcal{D}$. Let $B_0$ and $B_1$ be the ROBDDs spanned by the low and high child of $R_B$, respectively, representing functions $f_0$ and $f_1$ with associated functions $\rho_0,\rho_1,\hat{\beta}_0,\hat{\beta}_1$. Then $f \equiv (\neg d \wedge f_0) \vee (d \wedge f_1)$. Hence for $\vec{\delta} \in \mathbb{B}^{\mathcal{D}\setminus\{d\}}$ we get 
\begin{align*}
\hat{\beta}_D(\vec{\delta},0) &= \hat{\beta}_{D,0}(\vec{\delta}),\\
\hat{\beta}_D(\vec{\delta},1) &= \hat{\beta}_{D,1}(\vec{\delta}) \otimes_D \beta_D(d),\\
\rho(\vec{\delta},0) &= \rho_0(\vec{\delta}),\\
\rho(\vec{\delta},1) &= \rho_1(\vec{\delta}).
\end{align*}
Furthermore, write $\varphi(\vec{\delta}) := \hat{\beta}(\vec{\delta},\rho(\vec{\delta}))$; we define $\varphi_0$ and $\varphi_1$ likewise. Thus $\hat{\beta}(\mathcal{S}) = \varphi(\mathbb{B}^{\mathcal{D}})$. Then it follows that
\begin{align*} 
&\mathtt{Z}(B,R_B)\\
&= \underline{\min}_{\sqsubseteq}\Bigg(\mathtt{Z}(B_1,R_{B_1}) \\
& \ \ \cup \left\{(s \otimes_D \beta_D(d),t) \ \middle|\ (s,t) \in \mathtt{Z}(B_2,R_{B_2})\right\} \Bigg)\\
&= \underline{\min}_{\sqsubseteq}\Bigg(\underline{\min}_{\sqsubseteq}(\varphi_0(\mathbb{B}^{\mathcal{D}\setminus\{d\}})\\
& \ \ \cup \underline{\min}_{\sqsubseteq}\left\{(\hat{\beta}_{D,1}(\vec{\delta}) \otimes_D \beta_D(d),\hat{\beta}_A(\rho_1(\vec{\delta}))\ \middle|\ \vec{\delta} \in \mathbb{B}^{\mathcal{D}\setminus\{d\}} \right\} \Bigg)\\
&= \underline{\min}_{\sqsubseteq}\left(\underline{\min}_{\sqsubseteq}(\varphi(\mathbb{B}^{\mathcal{D}\setminus\{d\}} \times \{0\})) \cup \underline{\min}_{\sqsubseteq}(\varphi(\mathbb{B}^{\mathcal{D}\setminus\{d\}} \times \{1\})) \right)\\
&= \underline{\min}_{\sqsubseteq}(\varphi(\mathbb{B}^{\mathcal{D}})) = \underline{\min}_{\sqsubseteq}(\hat{\beta}(\mathcal{S})).
\end{align*}
which completes the proof by induction.
\end{proof}
