	\includegraphics[trim=0cm 4.5cm 0cm 2.5cm, clip,width=0.4\textwidth]{plot_reference_points.pdf}
	\caption{Structured reference points set for a three-objective problem with p = 4~\protect\cite{DebJ14}.}
