\begin{algorithm}[tb]
	\caption{Normalization}
	\label{alg:normalization}
	\begin{algorithmic}[1]
		\REQUIRE $F_1,\dots,F_{i^*}$: non-dominated fronts
            \item[]  \hspace{\algorithmicindent} \space $f=(f_1,...,f_M)$: objective function
		\item[]  \hspace{\algorithmicindent} \space $z^*\in \R^M$: observed $\min$. in each objective
		\item[]  \hspace{\algorithmicindent} \space $z^w\in \R^M$: observed $\max$. in each objective
		\item[]  \hspace{\algorithmicindent} \space $E\subseteq\R^M$: extreme points of previous iteration, initially $\{\infty\}^M$
		\FOR {$j=1$ \textbf{to} $M$}  
		\STATE $\hat{z}_j^*=\min\{z_j^*,\min_{z\in Z}f_j(z)\}$
		\STATE Determine an extreme point $e^{(j)}$ in the $j$th objective from $R\cup E$ using an achievement scalarization function
		\ENDFOR
		\STATE $valid =$ False																					
		\IF {$e^{(1)},...,e^{(M)}$ are linearly independently}
		\STATE $valid =$ Ture
		\STATE Let $H$ be the hyperplane spanned by $e^{(1)},...,e^{(M)}$
		\FOR {$j=1$ \textbf{to} $M$}
		\STATE $I_j=$ the intercept of $H$ with the $j$th objective axis
		\IF {$I_j\ge\epsilon_{\nad}$ and $I_j\le z_j^w$}
		\STATE $\hat{z}_j^{\nad} = I_j$ \label{line:znad}
		\ELSE
		\STATE $valid =$ False
		\STATE \textbf{break}
		\ENDIF
		\ENDFOR
		\ENDIF 
		\IF {$valid =$ False}
		\FOR {$j=1$ \textbf{to} $M$}
		\STATE $\hat{z}_j^{\nad}=\max_{x\in F_1}f_j(x)$
		\ENDFOR
		\ENDIF
		\FOR {$j=1$ \textbf{to} $M$}
		\IF {$\hat{z}_j^{\nad}<\hat{z}_j^*+\epsilon_{\nad}$}
		\STATE $\hat{z}_j^{\nad}=\max_{x\in F_1\cup\dots\cup F_{i^*}}f_j(x)$
		\ENDIF
		\ENDFOR
		\STATE Define $f_j^n(x)=(f_j(x)-\hat{z}_j^{*})/(\hat{z}_j^{\nad}-\hat{z}_j^{*})$  \space $\forall x\in \{0,1\}^n, j\in \{1,...,M\}$
	\end{algorithmic}
\end{algorithm}

