\begin{algorithm}[tb]
	\caption{Selection based on a set $U$ of reference points when maximizing the function $f$}
	\label{alg:selection}
	\begin{algorithmic}[1] % The [1] ensures that lines are numbered
		\REQUIRE $Z_t$: the multi-set of already selected individuals
		\item[]  \hspace{\algorithmicindent}  \space\space  $F_i^*$: the multi-set of individuals to choose from
		\STATE $f_n = \text{Normalize}(f, Z=Z_t \cup F_i^*)$ using Algorithm~\ref{alg:normalization}
		\STATE Associate each individual $x \in Z_t \cup F_i^*$ to the reference point rp$(x)$
		\STATE For each reference point $r \in U$, let $\rho_r$ denote the number of (already selected) individuals in $Z_t$ associated with $r$ \label{stp:niche}
		\STATE $U' = U$
		\STATE $\tilde{F}_{i^*} = \emptyset$
		\WHILE{True}
		\STATE Let $r_{\min} \in U'$ be such that $\rho_{r_{\min}}$ is minimal (break ties randomly)
		\STATE Let $x_{r_{\min}} \in F_{i^*} \setminus \tilde{F}_{i^*}$ be the individual that is associated with $r_{\min}$ and minimizes the distance between $f_n(x_{r_{\min}})$ and $r_{\min}$ (break ties randomly)
  % , \rz{If $\rho_{r_{\min}}\ge 1$, $x_{r_{\min}}$ is randomly selected.}) 
  %\merk{what is $x_{r_{\min}}$, do we have the definition before?}
		\IF{$x_{r_{\min}}$ exists}
		\STATE $\tilde{F}_{i^*} = \tilde{F}_{i^*} \cup \{x_{r_{\min}}\}$
		\STATE $\rho_{r_{\min}} = \rho_{r_{\min}} + 1$ \label{stp:rhoplus}
		\IF{$|Z_t| + |\tilde{F}_{i^*}| = N$}
		\STATE \textbf{break all} and \textbf{return} $\tilde{F}_{i^*}$
		\ENDIF
		\ELSE
		\STATE $U' = U' \setminus \{r\}$
		\ENDIF
		\ENDWHILE
	\end{algorithmic}
\end{algorithm}

\subsection{\omm and Approximation Metric}
As mentioned before, the bi-objective \omm~\cite{GielL10} is the only benchmark used in the theoretical community to analyze the approximation ability of the \NSGA-type algorithms~\cite{ZhengD22gecco,ZhengD24approx}. For a good comparison, this work also chooses this bi-objective benchmark (and also the approximation metric used in these works) to analyze the approximation ability of the \NSGAT. We believe the techniques and the insights obtained in this work will be useful for the analysis for many objectives.

% \wj{(Delete all before my next modification)}This paper consider the approximation ability of the \NSGAT for bi-objective pseudo-Boolean problems. Here are the basic concepts. A bi-objective pseudo-Boolean maximization problem is to maximize $f=(f_1,f_2):\{0,1\}^n \rightarrow \R$. For $x, y \in \{0,1\}^n$, we say that $x$ \textit{weakly dominates} $y$, denoted as $x\succeq y$, if $f_1(x)\ge f_1(y)$ and $f_2(x)\ge f_2(y)$. If at least one of the two inequalities is strict, we say that $x$ \textit{dominates} $y$, denoted as $x\succ y$. If $x$ is not dominated by any individual in $\{0,1\}^n$, it is called \textit{Pareto optimal}, and the set of function values corresponding to all Pareto optimal solutions forms the \textit{Pareto front}.

% The aim in multi-objective optimization is typically to find the whole Pareto front or an approximation of it. 
% Since the approximation theory of the \NSGA~\cite{ZhengD22gecco,ZhengD24approx} considers the \omm problem, our work for the first approximation theory of the \NSGAT will also consider this problem. See the following definition.\\

The \omm function is defined as follows, and we consider its maximization.
\begin{definition}[\cite{GielL10}]
For all search points $x$ the objective function $f:\{0,1\}^n\rightarrow \N \times \N$ is defined by
\begin{align*}
f(x)=(f_1(x),f_2(x))=\left(\sum_{i=1}^n x_i, n-\sum_{i=1}^n x_i\right).
\end{align*}
\end{definition}

In the language of multi-objective optimization, we say that $x$ \textit{weakly dominates} $y$, denoted as $x\succeq y$, if $f_1(x)\ge f_1(y)$ and $f_2(x)\ge f_2(y)$. If at least one of the two inequalities is strict, we say that $x$ \textit{dominates} $y$, denoted as $x\succ y$. If $x$ is not dominated by any individual in $\{0,1\}^n$, it is called \textit{Pareto optimal}, and the set of function values corresponding to all Pareto optimal solutions forms the \textit{Pareto front}. It is easy to see that the Pareto front of \omm is $\{(0,n),(1,n-1),\dots, (n,0)\}$, with a size of $n+1$.

As in the \NSGA's approximation theory~\cite{ZhengD22gecco,ZhengD24approx}, we will use the maximum empty interval (\mei) metric (See Definition~\ref{def:mei}) to evaluate how the algorithm approximates the Pareto front w.r.t. \omm. Note that the \mei can be easily transferred to other commonly used approximation metrics (like $\epsilon$-dominance~\cite{LaumannsTDZ02} and Hypervolume~\cite{ZitzlerT98})~\cite{ZhengD24approx}. 
\begin{definition}[\cite{ZhengD22gecco,ZhengD24approx}]\label{def:mei}
Let $S=\{(s_1,n-s_1), \dots, (s_m, n-s_m)\}$ be a subset of Pareto front $M$ of \oneminmax. Let $j_1,j_2,\dots,j_m$ be the sorted list of $s_1,\dots, s_m$ in the increasing order (ties broken uniformly at random). We define the maximum empty interval size of $S$, denoted by $\mei(S)$, as
\begin{align*}
\mei(S) = \max\{ j_1, n-j_m, j_{i+1}-j_i\mid \\i=1,\dots, m-1\}.
\end{align*}
For $n\in \N_{\ge 2}:=\{i\ge 2\mid i\in \N\}$, we further define
\begin{align*}
	\mei_{\opt}(N):=\min\{\mei(S)\mid &S\subseteq M,|S|\le N,\\&(0,n)\in S,(n,0)\in S\}.
\end{align*}
Obviously, this is the smallest \mei that an MOEA with a fixed population size $N$ can obtain when the extremal points $(0, n)$ and $(n, 0)$ are covered.
\end{definition}
The optimal $\mei$ value is shown in the following. Our work will obtain the upper bound of the \mei that the \NSGAT will achieve w.r.t. the \omm.
\begin{lemma}[\cite{ZhengD22gecco,ZhengD24approx}]\label{lem:meiopt}
For all $N\in \N_{\ge 2}$, we have $\mei_{\opt}(N) = \lceil\frac{n}{N-1}\rceil$.
\end{lemma}

\section{Approximation Guarantee when $N_r\le N$}\label{sec:app}
In this section, we will theoretically prove that when the number of reference points $N_r \leq N$, the \NSGAT can effectively approximate the Pareto front of the \omm problem.

\subsection{Reach Extremal Points}
To ease the discussion, here we call any optimal solution of one objective in a multiobjective problem an \emph{extremal point}. Note that it is not the same as the extreme point/vector used to determine the hyperpane, see in Algorithm~\ref{alg:normalization}. For \omm, $0^n$ and $1^n$ are the only extremal points. We will consider whether the two extremal points $0^n$ and $1^n$ can be reached. 

% \wj{(Delete)}Since the survival selection in the \NSGAT is complicated, \\
To achieve this, the following lemma will first show that for $N_r\le N$, the maximal and minimal objective values in the combined population survives. The key point is that after the normalization, such values will be mapped to $(1,0)$ or $(0,1)$. Note that $(1,0)$ and $(0,1)$ are reference points. Hence, the above values is closest to such reference points. Since $N_r\le N$ and all solutions are in $F_1$, we know that to select $N$ individuals in the survival selection in Algorithm~\ref{alg:selection}, the final $\rho_{r_{\min}}$ must be greater than or equal to $1$. Thus, before $\rho_{r_{\min}} > 1$, at least one individual with the maximal or minimal objective value (normalized to $(1,0)$ or $(0,1)$) will be selected into the next generation. Due to the pages limit, all proofs were moved to the supplementary material.

