% $$
% \frac{\binom{2N-1}{N-1}}{\binom{2N}{N}}=\frac{\frac{(2N-1)!}{N!(N-1)!}}{\frac{(2N)!}{N!N!}}=\frac{N}{2N}=\frac 12.
% $$
